INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'SUM001','C009','M01','[호랑이 형님]을 통해 문장부호를 익히며 경험과 연계해 교훈을 이해하고, 호랑이 형님을 소개하는 글을 씁니다.','[여우와 두루미]를 읽고 올바르게 띄어읽는 방법을 익히며 주제와 연계해 교훈을 이해하고, 그림일기를 씁니다.','[모두 모두 한집에 살아요]를 통해 문장의 구성성분을 배우고, 사회와 연계해 주제를 이해하며 초대장 쓰기를 합니다.','[제인 구달]을 읽고 흉내 내는 말의 종류와 쓰임을 이해하고, 위인과 연계해 업적과 배울점을 배우며 편지를 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'SUM002','C009','M02','[구름놀이]를 통해 흉내 내는 말의 쓰임을 알아보고 기본문장을 적어 본 다음 모습을 상상하는 글을 씁니다.','[호랑이와 곶감]을 통해 등장인물의 입장에서 상황을 살피고 소도둑의 입장에서 일기를 씁니다. ','[괜찮아, 우리 모두 처음이야!]를 통해 세 주인공의 마음에 공감하며 스토리를 이해하고, 학교의 이모저모를 알아보며 학생증을 만듭니다.','[헬렌 켈러]이야기에서 장애를 극복한 헬렌과 설리번 선생님의 일화를 정리하고, 설리번 선생님께 마음을 전하는 편지를 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'SUM003','C009','M03','[코끼리가 꼈어요]를 수업하며 흉내 내는 말을 넣어 문장을 완성한 후 특징을 소개하는 글을 씁니다.','[인사를 나눠드립니다]을 통해 상황에 맞는 인사말의 종류를 정리하고, 인사가 가진 힘을 알아본 후 인사말 쪽지쓰기를 합니다.','[백설공주]을 통해 ''그림형제'' 작가의 또 다른 작품을 알아보고, 대인 안전사고 예방수칙을 정리한 후 편지를 써봅니다.','[마더 테레사]의 일생과 업적을 정리하고 당시 인도가 어떤 상황에 처했는지 살피며 상장 만들기를 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'SUM004','C009','M04','[도서관 고양이]를 수업하며 흉내 내는 말을 넣어 문장을 완성한 후 특징을 소개하는 글을 씁니다.','[미운 아기 오리]를 통해 ''차별''에 대해 생각해보고 자아존중감에 대해 주제와 연계한 후 뒷 이야기를 완성해 봅니다.','[얍, 감기야 덤벼라!]를 읽고 우리 몸과 관련된 인체 · 과학상식을 정리하고, 건강관리 수업을 기록하며 올바른 약속을 다짐해 봅니다.','[마리 퀴리]를 통해 위인의 업적을 통해 꿈을 이룬 여성 과학자의 삶을 만나고 마리 퀴리의 입장이 되어 소감문 쓰기를 합니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'SUM005','C009','M05','[아빠가 아플 때 ]를 수업하며 성격과 생김새를 나타내는 말을 배워보고, 감사의 마음을 담은 상장을 만들어 봅니다. ','[맛있는 건 맛있어]를 읽고 음식과 관련된 자신의 경험을 발표하고, 내가 좋아하는 음식을 소개하는 글을 씁니다.','[달 샤베트]를 읽고 정전의 개념을 재미있는 동화로 이해하고, 전기를 절약하기 위한 선언문을 씁니다. ',' [엉뚱한 꼬마화가 김홍도]를 통해 조선시대와 연계해 풍속화에 대해 알아보고 현재 내가 살고 있는 시대를 반영한 풍속화 그리기를 합니다');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'SUM006','C009','M06','[빨간부채 파란부채]를 수업하며 의성어-의태어로 한문장 쓰기를 완성하고, 인상 깊은 장면을 발표하는 시간을 가집니다. ','[화내지 말고 예쁘게 말해요]를 읽고 ''나전달법''으로 기분을 전달하는 법을 배운 후, 경험을 담은 생활문을 씁니다.','[태극기 다는 날]을 읽고 우리나라의 상징과 태극기에 관련된 새로운 사실을 배우고 보고서 쓰기를 합니다.','[진짜 대장 이순신]을 통해 임진왜란의 역사를 이해하고, 이순신의 업적을 만나본 후 상상일기를 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'SUM007','C009','M07','[소금을 만드는 맷돌]을 수업하며 문장을 이어주는 접속사를 배운 후 접속사에 유의하여 일기쓰기를 합니다.','[진짜 일 학년 책가방을 지켜라]를 읽고 나의 생활과 연계해 생각을 펼치고, 경험을 담은 생활문을 씁니다.','[나는 안내견이야]를 읽고 시각장애인과 안내견에 대한 새로운 지식을 배우고, 사실을 전달하는 설명문을 씁니다.','[아멜리아 에어하트]를 통해 꿈을 향해 도전한 주인공의 일생을 만나고 나의 꿈을 소개하는 글을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'SUM008','C009','M08','[흥부 놀부]를 통해 새로운 어휘를 정리하고, 한옥의 종류를 만나며 전통문화를 알아봅니다. 그리고 흥부놀부의 성격을 파악한 후 뒷이야기 쓰기를 통해 수업을 마무리합니다.','[효녀 심청]을 통해 낯선 어휘의 뜻을 알아보고, 임금과 백성의 생활을 비교하며 전통문화를 정리합니다. 또, 심청의 효에 대한 자신의 의견을 밝히고 안내문을 써 봅니다.','[옹고집]을 읽고 어휘를 확장하며 원님(사또)의 역할을 알아보며 전통문화를 만납니다. 그리고 옹고집의 성격을 ''놀부''와 연관지어 비교해 보고 소개하는 글을 씁니다.','[고전정리 및 독서감상화] 시간에는 고전 세 작품의 주요핵심과 교훈을 정리하고, 나만의 독서감상화를 완성해 봅니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'SUM009','C009','M09','[대단한 참외씨]를 읽고 사건이 일어난 차례를 살핀 후 쌍받침, 겹받침에 맞게 단어를 쓰고 등장인물의 입장에서 소감문을 씁니다.','[마음이 그랬어]를 읽고 주인공의 마음변화를 따라가며 공감한 후 마음을 전달하는 편지쓰기를 합니다.','[해와 바람]을 읽고 새로운 지식으로 해의 역할과 바람의 원리를 배운 후 연극대본 쓰기를 합니다. ','[마틴 루서 킹]을 통해 평화의 방법으로 맞선 마틴 루서 킹의 일생을 만나고 인터뷰 글을 씁니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'SUM010','C009','M10','[소금을 만드는 맷돌]을 통해 두 가지 이상의 의미를 담고있는 다의어를 정리하고, 접속사에 유의하여 일기쓰기를 완성해 봅니다.','[아주 무서운 날]을 통해 을 통해 주인공이 겪은 일과 나의 경험을 연계한 후, 상황에 맞는 말하기로 생각을 정리하고 독서감상문을 씁니다.','[이솝우화]를 읽고 작가 ''이솝''에 대해 알아보고 동화 속 까마귀가 발견한 부력의 원리를 이해한 후 도구를 사용하는 동물의 종류를 알아봅니다.  ','[세종대왕]을 통해 조선시대 한글창제의 의의를 짚어보고, 한글의 소중함을 되새기며 세종대왕에게 보내는 감사편지를 적어봅니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'SUM011','C009','M11','[신기한 독] 이야기를 통해 낯선 어휘의 뜻을 알아보고, 문장을 완성한 후 인과관계에 유의하여 상상하는 글을 완성해 봅니다.','[브로콜리지만 사랑받고 싶어]를 읽고 자신을 사랑하며 존중하는 ''나다움''의 의미를 알아보고, 주인공에게 전하는 편지를 씁니다. ','[얍, 감기야 덤벼라!]를 읽고 우리 몸과 관련된 인체 ·과학상식을 정리하고, 건강관리 수업을 기록하며 올바른 약속을 다짐해 봅니다.','[신사임당]을 통해 조선시대 여성들의 생활을 알아보고, 다양한 각도로 업적을 정리한 후 소개하는 글쓰기를 완성합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'SUM012','C009','M12','[소가 된 게으름뱅이]를 통해 주인공이 겪은 일을 차례대로 말해보며 성격을 나타내는 반대말을 정리합니다.','[붉은 여우 아저씨]를 읽고 나눔의 중요성을 알아보고 주제연계도서를 비교하여 자신의 생각을 발표해 봅니다. ','[감기 걸린 날] 이야기를 통해 위험에 처한 동물들의 모습을 만나고, 감기의 원인과 예방법을 알아본 후 주인공에게 보내는 편지를 씁니다.','[김만덕]을 읽고 조선시대 제주도의 사회 모습을 알아보고 나눔을 실천한 자세를 생각한 후 기념비에 들어갈 내용을 정리해 봅니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'DUM001','C0010','M01','[브레멘의 동물음악대]를 읽고 그림형제와 독일여행을 떠나 문화를 알아보고, 동물을 대하는 주인들의 잘못을 발표한 후 뒷이야기 이어쓰기를 합니다.','[80일간의 세계일주]를 통해 쥘베른과 세계 여러나라를 여행하며 시공간을 확장하고, 문화와 풍습을 정리한 후 나의 경험을 담은 기행문을 씁니다. ','[왕자와 거지]를 읽고 영국의 절대왕권의 배경을 알아보고, 신분제도에 대한 자신의 의견을 밝히며 토론한 후 작품 속 등장인물에게 편지쓰기를 합니다.','[600자 독서감상문]배운 작품을 정리하고, 가장 인상깊은 작품을 선택한 후 개요짜기를 바탕으로 600자 독서감상문을 완성합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'DUM002','C0010','M02','[나는 나의 주인]을 읽고 문장을 이어주는 접속사를 배우고 문장으로 완성하고, 소개하는 글을 씁니다.','[세상에 둘도 없는 반짝이 신발]을 통해 시간의 흐름에 따라 주인공의 마음변화를 살핀 후 주인공에게 전하는 편지를 씁니다.','[7년 동안의 잠]이야기 속 매미의 한살이에 대해 알아보고, 곤충의 탈바꿈 과정을 정리한 후 관찰기록문 쓰기를 합니다.','[별 헤는 아이 윤동주]를 통해 일제 강점기 시대를 살았던 윤동주의 삶을 알아보고 시대상을 정리하며 인터뷰 글을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'DUM003','C0010','M03','[설문대할망]을 읽고 설화 속 이야기를 만난 후 문장부호에 맞게 띄어쓰기를 하며 독서감상문을 써봅니다.','[아기 토끼와 채송화 꽃]이야기 속 두 편을 수업하며 이야기 속 주제를 찾아보고, 인물의 마음을 짐작 한 후 일기를 씁니다.','[어디 갔을까, 쓰레기]를 통해 환경문제를 짚어보고 북태평양 쓰레기 섬의 실태를 알아보며 주장하는 글을 씁니다.','[나이팅게일]의 일생을 정리하며 당시 영국사회의 모습을 짚어보고, 테레사 수녀와 비교해서 공통점을 찾은 후 기사문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'DUM004','C0010','M04','[토끼의 재판]을 통해 어려운 어휘의 뜻을 짚어보고, 어휘를 적용해 문장을 만든 후 자신의 생각을 담은 주장하는 글을 씁니다.','[누구를 보낼까요]이야기를 통해 ''민주주의'' 의사결정 방법에 대해 생각해보고, 자신의 의견이 잘 드러나도록 편지를 적어봅니다. ','[신발 신은 강아지]를 통해 유기견의 실태와 동물 보호소의 역할에 대해 알아보고, 반려동물과 함께 지내는 방법을 알리는 설명문을 씁니다.','[마법의 손 장영실]을 통해 조선시대 신분제도에 대한 자신의 생각을 정리하고, 장영실의 업적인 조선 최고의 과학 발명품을 만납니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'DUM005','C0010','M05','[금을 버린 형제]를 통해 다양한 속담의 종류와 쓰임을 알아보고, 생각과 느낌을 담은 독서감상문을 씁니다.','[해와 달이 된 오누이]이야기를 통해 구성이 비슷한 명작과 작품을 비교해 보고, 교훈이 드러나는 동화쓰기를 합니다.','[어슬렁어슬렁 동네 관찰기]를 통해 도시가 생겨난 이유를 알아보고 다양한 직업군에 대해 만난 후 내가 사는 동네를 설명하는 글을 씁니다.','[프리다 칼로]를 통해 장애를 뛰어넘은 화가의 삶을 만나고 멕시코 문화의 특징을 배운 후 자화상을 그리며 나 자신을 돌아봅니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'DUM006','C0010','M06','[팥죽할머니와 호랑이]를 통해 관용어의 종류와 쓰임을 알아보고, 리듬감이 느껴지는 동시쓰기를 합니다.','[개구리와 두꺼비는 친구]이야기를 통해 진정한 우정에 대한 자신의 생각을 발표하고, 주인공의 입장이 되어 편지쓰기를 합니다.','[살색은 다 달라요]를 통해 다문화 사회에 대한 개념을 정리하고, 세계 여러나라의 문화를 만난 후 생각과 느낌을 담아 독서감상문을 씁니다.','[장기려]를 통해 6-25전쟁의 역사를 이해하고, 희생과 봉사의 업적을 정리한 후 육하원칙에 맞춰 기사문 쓰기를 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'DUM007','C0010','M07','[엉뚱한 수리점]을 통해 뜻을 분명히 해주는 부사어의 종류와 쓰임을 배우고 부탁하는 글쓰기를 합니다.','[치과의사 드소토 선생님]이야기를 통해 등장인물의 성격변화를 살피고, 주인공의 입장에서 상상편지를 씁니다.','[시끌시끌 소음공해 이제 그만]을 통해 소음발생의 원인과 문제점을 알아본 후 소음공해를 막기 위한 주장하는 글을 씁니다.','[유관순]을 통해 일제강점기 시대상을 이해하고, 독립운동가의 업적을 살핀 후 상장만들기를 합니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'DUM008','C0010','M08','[주몽, 고구려를 세우다]를 읽고 건국신화로 고구려의 인물-사건을 정리하며 역사를 만납니다. 또, 인물 관계도를 통해 백제의 건국 이야기까지 함께 다룬 후 역사퀴즈로 수업을 마무리합니다.  ','[박혁거세, 신라를 세우다]를 읽고 신라의 건국신화를 정리하며 신라의 문화재를 만납니다. 그리고 박혁거세를 통해 임금의 자격에 대해 생각을 나눈 후 역사퀴즈로 수업을 정리합니다.','[철의 나라 가야]를 읽고 가야의 건국신화로 스토리를 정리하고 가야의 역사적 사실을 정리합니다. 또, 난생신화의 의의를 정리한 후 역사퀴즈로 수업을 마칩니다.','[건국신화정리+독서감상문]시간에는 삼국의 건국신화 속 핵심을 정리하고 인상 깊은 스토리를 되돌아 보며 독서감상문 쓰기를 합니다.  ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'DUM009','C0010','M09','[할머니와 하얀집]을 통해 올바른 맞춤법을 적용해 문장쓰기를 하고 주제에 맞게 뒷이야기 이어쓰기를 합니다.','[거인의 정원] 이야기를 읽고  같은 주제를 다룬 작품을 비교한 후 거인의 마음변화를 이해하고 추천하는 글을 씁니다.','[오염물이 터졌다]를 통해 오염물이 만들어지는 원인과 물오염을 막는 방법에 대해 알아본 후 주장하는 글을 완성해 봅니다.','[선덕여왕]을 통해 삼국시대 역사를 이해하고, 선덕여왕의 업적을 정리한 후 인물의 입장이 되어 자기소개서를 써 봅니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'DUM010','C0010','M10','[팥죽 할머니와 호랑이]를 통해 등장 인물의 특징을 꾸며 주는 말을 이해하고, 리듬감이 느껴지는 동시 한 편을 완성해 봅니다.','[언제나 칭찬]을 통해 진정한 칭찬이 가진 힘에 대해 이야기 나눠보고, 이야기 속 인과관계를 생각하며 편지쓰기를 해봅니다. ','[오염물이 터졌다!]를 읽고 수질오염의 원인과 문제점을 알아보고, ''물오염을 막고 물을 절약하자''는 주제로 주장하는 글을 적어봅니다.','[주시경]을 통해 한글을 사랑한 국어학자의 업적을 만나고 개화기의 사회 모습을 알아본 후 인물신문을 완성해 봅니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'DUM011','C0010','M11','[쿵푸 아니고 똥푸]의 ''오, 미지의 택배'' 이야기를 통해 올바른 맞춤법에 맞게 문장을 완성하고 뒷이야기를 상상해서 동화 이어쓰기를 합니다.','[아낌없이 주는 나무]을 통해 나무와 소년의 행동에 대한 자신의 생각을 밝히고, 올바른 토론 규칙을 지키며 열띤 토론의 시간을 가져봅니다.','[긴긴 겨울잠에 폭 빠진 동물들]을 읽고 겨울잠을 자는 동물들의 생체변화를 알아보고, 설명하는 글을 완성해 봅니다.','[모차르트]를 읽고 음악을 사랑한 천재 음악가의 삶을 이해하고, 오페라 작품을 감상한 후 연주회 포스터를 만들어 봅니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'DUM012','C0010','M12','[밥상에 우리 말이 가득하네]를 통해 음식에서 유래된 우리말 어휘와 속담을 알아보고 생활문 쓰기를 완성합니다.','[아씨방 일곱 동무]를 읽고 주제와 관련된 자신의 생각을 밝히고, 여러 물건이 모여 하나의 일을 할 수 있는 요소를 찾아 재미있는 동화쓰기를 합니다.','[행복한 왕자]를 통해 기부의 중요성을 이해하고, 기부를 실천한 대표적인 인물을 통해 ''노블레스 오블리주''의 개념을 정리합니다.','[슈바이처]를 통해 1차 세계대전의 시대상을 알고, 나눔과 봉사의 삶을 실천하여 노벨 평화상의 주인공이 된 슈바이처의 삶을 배웁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'TUM001','C0011','M01','1월은 <교과 미리보기 특강>을 진행합니다. [돼지책]을 읽고 옛날과 오늘날의 가족 구성원의 역할 변화를 정리하고 우리 가족의 모습과 연관지어 역할 변화가 필요한 사람에게 편지를 적어봅니다.','[신석기 시대의 봄, 여름, 가을, 겨울]을 통해 신석기 시대의 생활 모습과 도구를 알아보고, 새롭게 알게 된 내용을 바탕으로 설명문 쓰기를 합니다.','[자석 삼킨 강아지]를 통해 자석의 성질을 실험관찰을 통해 알아보고 생활 속 자석의 성질을 이용한 물건을 정리하며 관찰 기록문을 씁니다.*준비물 : 막대자석 2개','<600자 독서감상문> 배운 작품을 정리하고, [자석 삼킨 강아지] 개요짜기를 바탕으로 600자 독서감상문을 완성합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'TUM002','C0011','M02','2월은 <인권>을 주제로 수업합니다. [헬렌켈러]를 읽고, 보지도 듣지도 못 했던 헬렌 켈러의 마음에 공감해봅니다. -정독이해: 줄거리 이해를 바탕으로 문해력 키우기 -창의 사고 활동: 만약 내가 감각을 느낄 수 없다면 어떨지 생각해보기 -주제 글쓰기: 헬렌 켈러가 되어 일기쓰기','장애인 차별 문제에 대해 생각해봅니다. -핵심개념: 장애인에 대한 개념 알아보기 -심화적용: 장애인 차별 모습을 알아보며 사실과 의견 나누기
-주제 글쓰기: ‘장애인과 더불어 살자’는 주장하는 글쓰기','[진짜 투명인간]을 읽고, 시각장애인의 어려움에 대해 공감해봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-선천적 장애인이 후천적 장애인보다 더 힘들다.
-쓰기: 토론 결과 쓰기','<진짜 투명인간>
시각장애인 블링크 아저씨와 에밀의 우정을 생각하며 800자 원고지에 독후감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'TUM003','C0011','M03','3월은 <환경>을 주제로 수업합니다.
[투발루에게 수영을 가르칠 걸 그랬어!]를 읽고, 점점 가라앉는 투발루에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-창의 사고 활동: 지구 온난화와 투발루
-주제 글쓰기: 환경 신문 만들기','다양한 생물의 터전인 갯벌에 대해 알아봅니다.
-핵심개념: 갯벌의 의미와 갯벌에 사는 생명들
-심화적용: 인간의 욕심으로 파괴되는 갯벌
-주제 글쓰기: ‘병든 갯벌을 보호하자.’는 주장하는 글쓰기','[바삭바삭 갈매기]를 읽고, 바삭바삭을 찾아다니는 갈매기의 상황을 이해해봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-야생 갈매기에게 과자를 주어도 된다.
-쓰기: 토론 결과 쓰기','<바삭바삭 갈매기>
바삭바삭을 찾아 떠난 야생 갈매기의 상황을 생각하며 800자 원고지에 독후감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'TUM004','C0011','M04','4월은 <과학>을 주제로 수업합니다.
동물과 식물이 태어나는 [알과 씨앗]에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-창의 사고 활동: 내가 만든 씨앗
-주제 글쓰기: 알과 씨앗 설명하기 ','교통수단의 발전에 대해 알아봅니다.
-핵심개념: 옛날과 오늘날의 교통수단
-심화적용: 눈부시게 발전하는 교통수단
-주제 글쓰기: 라이트 형제에게 감사편지 쓰기','[우주쓰레기]를 읽고, 우주와 우주쓰레기에 대해 알아봅시다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-우주 개발을 지금 해야 한다.
-쓰기: 토론 결과 쓰기','<우주쓰레기>
우주에 떠다니는 쓰레기의 심각성을 알며 800자 원고지에 독후감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'TUM005','C0011','M05','5월은 <가족>을 주제로 수업합니다.
[마법의 설탕 두 조각]을 읽고, 가족과 소통하는 방법에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-창의 사고 활동: 렝켄의 마음에 공감하기
-주제 글쓰기: 렝켄의 부모님이 되어 렝켄에게 편지쓰기','변화하는 오늘날의 가족에 대해 알아봅니다.
-핵심개념: 가족의 변화와 구성원의 역할
-심화적용: 다양한 가족의 모습
-주제 글쓰기: 나의 가족 소개하기','[아드님, 진지드세요]를 읽고 상대를 생각하는 대화법에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-높임말 사용으로 범수의 버릇을 고쳐야 한다.
-쓰기: 토론 결과 쓰기','<아드님, 진지 드세요>
따뜻한 말의 힘을 알며 800자 원고지에 독후감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'TUM006','C0011','M06','6월은 <호국보훈>을 주제로 수업합니다.
[온양이]를 읽고, 흥남철수에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-지식확장: 6·25전쟁
-주제 글쓰기: 명호가 되어 일기 쓰기','우리나라 국기인 태극기에 대해 알아봅니다.
-심화적용: 우리 민족과 함께한 태극기
-서술형 단문 쓰기: 만세운동과 유관순
-주제 글쓰기: 유관순 열사 소개하기','[나는 안중근이다]를 읽고 우리나라를 대표하는 독립운동가, 안중근에 대해 알아봅시다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-내가 안중근이라면 총을 쏘고 도망가겠다.
-쓰기: 토론 결과 쓰기','<나는 안중근이다>
나라를 위해 목숨을 바친 안중근을 알고 800자 원고지에 독후감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'TUM007','C0011','M07','7월은 <꿈>을 주제로 수업합니다.
[행복한 청소부]를 읽고, 타인의 직업을 존중하는 마음에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-창의 사고 활동: 주인공 되어보기
-주제 글쓰기: ‘모든 직업은 소중하다.’ 주장하는 글쓰기','다양한 직업에 대해 알아봅니다.
-핵심개념: 직업의 뜻과 중요성
-심화적용: 직업의 종류
-주제 글쓰기: 나의 꿈 소개하기','[꺼벙이 억수와 꿈을 실은 비행기] 주변을 행복하게 하는 꿈에 대해 알아봅시다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-직업을 선택할 때 돈이 제일 중요하다.
-쓰기: 토론 결과 쓰기','<꺼벙이 억수와 꿈을 실은 비행기>
나와 이웃을 행복하게 하는 꿈을 알고 800자 원고지에 독후감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'TUM008','C0011','M08','8월은 <역사특강>을 진행합니다.
[힘찬 나라 고구려]를 읽고, 용맹하고 강인한 국가였던 고구려에 대하여 알아봅니다.
고구려 전성기 지도를 보며 한반도의 지붕이었던 고구려의 역할에 대해 생각해보고, 역사퀴즈로 수업을 마무리합니다.','[아름다운 나라 백제] 아름다운 문화를 꽃피운 백제에 대하여 알아봅니다.
백제의 역사와 문화를 확인하고, 삼국시대 한강이 중요했던 이유에 대해 함께 생각해 봅니다.','[슬기로운 나라 신라] 독특한 문화가 발달한 신라에 대하여 알아봅니다.
알에서 태어난 시조 임금에 대해 알아보고 그 의미를 생각해 본 후 역사퀴즈로 수업을 마무리 합니다. ','<삼국의 역사 및 연표정리>
각 나라별 중요 왕의 업적을 통해 삼국의 역사를 다시 한 번 정리해 보고 연표를 완성해 봅니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'TUM009','C0011','M09','9월은 <우정>을 주제로 수업합니다.
[거인 부벨라와 지렁이 친구] 있는 그대로 모습을 인정해주는 두 친구의 이야기에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-창의 사고 활동: 다른 점을 인정하는 법
-주제 글쓰기: 기행문 쓰기','나와 다른 친구를 아끼고 사랑하는 자세를 배웁니다.
-핵심개념: 친구와 우정
-심화적용: 우정이 소중한 이유
-주제 글쓰기: 절친한 친구 소개하기','[오성과 한음] 조선시대에 진정한 우정을 나눈 오성과 한음에 대하여 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-방안으로 팔을 넣은 오성의 행동은 정당하다.
-쓰기: 토론 결과 쓰기','<오성과 한음>
조선의 충신 ‘오성과 한음’의 우정을 생각하며 800자 원고지에 독후감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'TUM010','C0011','M10','10월은 <한글>을 주제로 수업합니다.
[아무말 대잔치] 주인공의 변화를 보며 상대방을 배려하는 대화에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-창의 사고 활동: 나의 언어생활 돌아보기
-주제 글쓰기: 찬우에게 응원의 편지쓰기','한글과 우리나라를 사랑한 한글학자 호머 헐버트에 대해 알아봅니다.
-핵심개념: 호머 헐버트와 육영 공원
-심화적용: 말과 글의 소중함
-주제 글쓰기: 호머 헐버트가 되어 연설문 쓰기','[세종대왕] 한글을 창제한 세종대왕의 삶과 업적을 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-세종대왕의 도천법은 옳다.
-쓰기: 토론 결과 쓰기','<세종대왕>
백성을 위하여 훈민정음을 창제한 ‘세종대왕’으로 800자 원고지에 독후감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'TUM011','C0011','M11','11월은 <고전>을 주제로 수업합니다.
[옹고집전]을 통해 고전작품의 주제인 ‘권선징악’에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-창의 사고 활동: 진짜 나를 증명하는 방법
-주제 글쓰기: 옹고집이 되어 일기 쓰기','전래동화에 대해 알아보고 주제에 대해 생각해봅니다.
-심화적용: 탐관오리를 벌하는 암행어사
-서술형 단문 쓰기: 어사 박문수 이야기
-주제 글쓰기: 정치인에게 편지 쓰기','효를 실천한 심청이의 이야기를 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-심청이는 효녀다.
-쓰기: 토론 결과 쓰기','<효녀 심청>
효를 실천한 심청이를 알고 800자 원고지에 독후감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'TUM012','C0011','M12','12월은 <나눔>을 주제로 수업합니다.
[빨간자전거] 부르키나파소의 모습을 살펴보며 아프리카 어린이들의 상황에 대하여 이해합니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-창의 사고 활동: 우리 반 기부 목록
-주제 글쓰기: 나눔 신문 만들기','나눔을 실천하는 올바른 마음에 대해 생각해 봅니다.
-핵심개념: 나눔과 기부
-심화적용: 다양한 기부
-주제 글쓰기: 비교하는 글쓰기','나눔의 중요성을 알았던 여성 기업가 김만덕에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-내가 김만덕이라면 전 재산을 나누어 줄 수 있다.
-쓰기: 토론 결과 쓰기','<김만덕>
나눔의 마음으로 백성을 살린 김만덕을 알고 800자 원고지에 독후감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'CUM001','C0012','M01','1월은 <역사특강>을 진행합니다.
[해동성국 발해]를 읽고 발해의 역사와 문화를 정리하고 발해가 우리의 역사인 이유에 대한 자신의 의견을 밝히고 역사 퀴즈로 마무리합니다.','[세계 속의 코리아 고려]를 읽고 고려전기의 역사와 문화를 정리하고 고려전기의 왕과 귀족의 역할에 비판해 본 후 지도 위에 영토를 완성합니다.','[몽골에 맞선 나라 고려]를 읽고 고려 후기의 역사와 문화를 정리하고 삼별초 항쟁을 통해 배울점을 적어 본 후 역사퀴즈로 수업을 마무리합니다.','[연표정리 및 독서감상문] 연표를 통해 배운 작품을 정리하고, 가장 인상깊은 시대를 선정해 독서감상문 쓰기를 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'CUM002','C0012','M02','2월은 <인권>을 주제로 수업합니다.
[루이브라유]를 읽고, 점자를 만든 루이 브라유에 대해 알아봅시다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-창의 사고 활동: 점자가 없는 불편함을 상상하고 해결방안 찾기
-주제 글쓰기: 루이 브라유가 되어 편지쓰기','인권이 무엇이고 왜 중요한지에 대해 알아봅니다.
-핵심개념: 인권과 세계인권선언 알아보기
-심화적용: 차별과 편견을 바꾸는 방법 생각하기
-주제 글쓰기: 스티븐 호킹이 되어 연설문 쓰기','[젓가락 달인]을 읽고, 다문화 가족을 알고 더불어 살아가기 위해 노력해봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-다문화 가정을 구분하는 것은 차별이다.
-쓰기: 토론 결과 쓰기','<젓가락 달인>
다름을 배워가는 우봉이를 이해하고 800자 원고지에 독후 감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'CUM003','C0012','M03','3월은 <환경>을 주제로 수업합니다.
[숨 쉬는 도시 꾸리찌바]를 읽고, 생태도시 꾸리찌바에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-창의 사고 활동: 브라질의 생태 도시
-주제 글쓰기: 환이가 되어 기행문 쓰기','물의 소중함에 대해 알아봅니다.
<오늘의 수업>
-핵심개념: 지구를 살아가게 하는 물
-심화적용: 수질 오염의 원인과 해결방안
-서술형 단문 쓰기: 환경문제에 대한 의견 쓰기
-주제 글쓰기: ‘수질 오염을 막자’로 주장하는 글쓰기','[숲에서 온 바람 윙윙]속 바람과 친구가 된 영범이의 이야기를 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-토종 식물은 식물원에서 키워야 한다.
-쓰기: 토론 결과 쓰기','<숲에서 온 바람 윙윙>
자연의 소중함을 알며 800자 원고지에 독서감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'CUM004','C0012','M04','4월은 <과학>을 주제로 수업합니다.
화산과 지진에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-창의 사고 활동: 지진을 견디는 건물
-주제 글쓰기: 화산과 지진 신문 만들기','무게와 중력의 관계에 대해 알아봅니다.
-핵심개념: 물체의 무게와 저울
-심화적용: 중력이란 무엇일까
-서술형 단문 쓰기: 중력에 따라 달라지는 무게
-주제 글쓰기: 우주 과학자에게 보내는 뉴턴의 편지','조선의 천재 과학자, 장영실에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-불량 가마 사건은 장영실의 책임이다.
-쓰기: 토론 결과 쓰기','<고정욱 선생님이 들려주는 장영실>
조선 최고의 과학자인 장영실을 본받으며 800자 원고지에 독후 감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'CUM005','C0012','M05','5월은 <가족>을 주제로 수업합니다.
[비밀소원]을 읽고, 가족의 변화를 받아들이며 성장하는 아이들에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-창의 사고 활동: ‘절친’의 의미와 가족에 대한 생각
-주제 글쓰기: 비밀 일기 쓰기','가족 갈등과 해결방안에 대해 알아봅니다.
-핵심개념: 가족 갈등과 해결방법
-서술형 단문 쓰기: 갈등이 일어났을 때 해결할 수 있는 법
-주제 글쓰기: 스마트폰 사용에 대한 갈등과 해결방안','다양한 가족의 모습에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-내가 영미라면 밤티 마을로 돌아간다.
-쓰기: 토론 결과 쓰기','<밤티 마을 큰돌이네 집>
변화를 겪으며 단단해진 밤티 마을 가족을 생각하며 800자 원고지에 독후 감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'CUM006','C0012','M06','6월은 <호국보훈>을 주제로 수업합니다.
[울보 엄마]를 읽고, 이산가족의 아픔에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-창의 사고 활동: 이산의 아픔을 되풀이 하지 않을 방법
-주제 글쓰기: 그리운 아버지께 안부 편지쓰기','분단에 대해 알아보고 평화로운 남과 북의 모습에 대해 생각합니다.
-심화적용: 남과 북, 따로 또 같이
-서술형 단문 쓰기: 북한 이탈주민
-주제 글쓰기: 함께하는 우리가 되기 위한 건의문','하나 된 나라를 꿈꿨던 김구의 삶에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-나라가 어려울 때 내 삶을 바쳐 일한다.
-쓰기: 토론 결과 쓰기','<김구>
자주독립과 통일을 꿈꿨던 김구를 알고 800자 원고지에 독후 감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'CUM007','C0012','M07','7월은 <꿈>을 주제로 수업합니다.
[6분 소설가 하준수]나를 행복하게 하는 꿈에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-창의 사고 활동: ‘세계 책의 날’을 알리는 포스터 만들기
-주제 글쓰기: 내가 주인공이 되는 소설 쓰기','우리가 꿈꾸는 사회에 대해 생각합니다.
-심화적용: 꿈으로 나라를 지킨 사람들
-서술형 단문 쓰기: ‘마틴 루서 킹’의 나에게는 꿈이 있습니다.
-주제 글쓰기: 나의 미래 일기 쓰기','[초희의 글방동무] 조선의 여성 시인, 허난설헌의 어린 시절에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-조선 시대 여성으로 글공부를 꿈꾼 것은 잘못이다.
-쓰기: 토론 결과 쓰기','<초희의 글방 동무>
자신의 꿈을 찾은 초희를 본받고 800자 원고지에 독후 감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'CUM008','C0012','M08','8월은 <역사특강>을 진행합니다.
[한국사 이야기] 선사시대 ~ 고조선과 여러 나라들의 역사와 문화에 대해 알아봅니다. 그리고 신석기 시대 사람들이 바위에 그림을 남긴 이유에 대해 생각해보며 자신의 의견을 이야기 해 봅니다. ','[한국사 이야기] 고구려와 백제의 역사와 문화에 대해 알아봅니다. 두 나라의 문화유산의 특징을 확인하고 직접 가보고 싶은 곳을 선정하여 문화유산 답사 계획을 적어봅니다. ','[한국사 이야기] 신라와 가야의 역사와 문화에 대해 알아봅니다.
고구려, 백제, 신라, 가야가 있던 시대를 ‘삼국시대’라고 부르는 이유에 대해 생각해 보고 의견을 적어봅니다. ','[한국사 이야기] 통일신라와 발해의 역사와 문화를 배우며 남북국시대에 대해 알아봅니다. 그리고 여름방학 특강을 마무리 하며 선사시대~남북국시대의 내용을 연표를 통해 정리해 봅니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'CUM009','C0012','M09','9월은 <우정>을 주제로 수업합니다.
[지우개 따먹기 법칙] 친구들과 아름다운 우정을 만들어가는 법을 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-창의 사고 활동: 나만의 ‘우정 키우기 법칙’ 만들기
-주제 글쓰기: 상보가 되어 일기쓰기','아름다운 우정을 가꾸는 방법에 대하여 알아봅니다.
-핵심개념: 마음을 알아주는 친구
-서술형 단문 쓰기: 친구의 마음을 이해하는 방법
-주제 글쓰기: 주장하는 글쓰기','[양파의 왕따일기1] 왕따 없는 학교를 만들기 위한 방법에 대하여 생각해봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-양파에 들어간 정화의 행동은 옳다.
-쓰기: 토론 결과 쓰기','<양파의 왕따 일기1>
왕따의 문제점을 생각하며 ‘양파의 왕따 일기 1’로 800자 원고지에 독서감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'CUM010','C0012','M10','10월은 <한글>을 주제로 수업합니다.
[독서 퀴즈 대회] 주인공의 마음에 공감하며 다양한 책을 읽어야 하는 이유에 대해 생각해봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-창의 사고 활동: 고전, 명작의 새로운 이름
-주제 글쓰기: 대회를 통해 성장한 수혜가 되어 일기쓰기','위대한 문화유산인 한글에 대해 알아봅니다.
-핵심개념: 백성을 가르치는 바른 소리
-서술형 단문 쓰기: 과도한 외국어를 사용하는 식품 업계에 대한 생각 쓰기
-주제 글쓰기: 주장하는 글쓰기','[주보따리, 한글을 지키다] 한글을 사랑하고 연구하였던 한글학자 주시경 선생님에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 외래어를 우리말로 바꾸어 사용해야 한다.
-쓰기: 토론 결과 쓰기','<주보따리, 한글을 지키다!>
훈민정음에 한글이라는 이름을 붙인 ‘주시경’으로 800자 원고지에 독후 감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'CUM011','C0012','M11','11월은 <고전>을 주제로 수업합니다.
책을 좋아했던 우리 조상에 대해 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-창의 사고 활동: 진정한 독서의 완성 3단계 독서법
-주제 글쓰기: 책을 좋아한 조상님과 상상 인터뷰하기','고전의 가치에 대해 알아봅니다.
-심화적용: 이야기에 노래를 붙인 판소리
-서술형 단문 쓰기: 흥부전의 특징과 교훈
-주제 글쓰기: 고전 작품 뒷이야기 완성하기','병자호란을 배경으로 만들어진 <박씨부인>에 대하여 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-사람의 외모는 중요하다.
-쓰기: 토론 결과 쓰기','<박씨부인>
병자호란에 대한 안타까움과 백성들의 소망을 담은 <박씨부인>으로 800자 원고지에 독후 감상문을 씁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'CUM012','C0012','M12','12월은 <나눔>을 주제로 수업합니다.
[콩 한쪽도 나누어요] 서로 도우며 따뜻한 세상을 만드는 방법을 알아봅니다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-창의 사고 활동: 사회봉사명령제도
-주제 글쓰기: 지진 현장을 다녀온 라오즈의 일기','진정한 선물을 주고받는 방법에 대해 생각해 봅니다.
-핵심개념: 선물과 뇌물
-심화적용: 크리스마스의 유래
-서술형 단문 쓰기: <크리스마스 선물>에서 배워야 할 점
-주제 글쓰기: 감사함을 전하는 편지 쓰기','공정무역에 대해 알아보고 도덕적인 소비를 홍보해봅시다.
-정독이해: 줄거리 이해를 바탕으로 문해력 키우기
-토론: 논제-모든 상품을 공정무역으로 바꾸자.
-쓰기: 토론 결과 쓰기','<공정무역, 행복한 카카오 농장 이야기>
공정무역을 이해하고 <공정무역, 행복한 카카오 농장 이야기>로 800자 원고지에 독후 감상문을 씁니다.');

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------

INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP001','C0014','P01','
이달의 인물 [따뜻한 마음 허준 선생님]
동화를 보며, 환자를 배려한 조선의 의사 ‘허준’을 만납니다.
동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.
','이달의 인물 [따뜻한 마음 허준 선생님]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 허준과 친구가 됩니다.','이달의 인물 [따뜻한 마음 허준 선생님]
허준이 쓴 최고의 의학책 동의보감에 대해 알아보며 새로운 지식을 접해봅니다.','이달의 인물 [따뜻한 마음 허준 선생님]
동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP002','C0014','P02','이달의 인물 [동물은 내 친구 제인구달]
동화를 보며, 침팬지를 존중한 동물학자 ‘제인구달’을 만납니다.
동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [동물은 내 친구 제인구달]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 제인구달과 친구가 됩니다.','이달의 인물 [동물은 내 친구 제인구달]
지도에서 아프리카를 찾고, 신비의 땅 아프리카에 대해 알아보며 새로운 지식을 접해봅니다.','이달의 인물 [동물은 내 친구 제인구달]
동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP003','C0014','P03','이달의 인물 [지갑 속의 효자 이이]
동화를 보며, 어머니를 사랑한 효자 ‘이이’를 만납니다.
동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [지갑 속의 효자 이이]
동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.','이달의 인물 [지갑 속의 효자 이이]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 이이와 친구가 됩니다.','이달의 인물 [지갑 속의 효자 이이]
우리나라 동전과 지폐 속 주인공에 대해 알아보며 새로운 지식을 접해봅니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP004','C0014','P04','이달의 인물 [함께 만든 훈민정음 세종대왕]
동화를 보며, 신하들과 협력하여 한글을 만든 ‘세종대왕’을 만납니다.
동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [함께 만든 훈민정음 세종대왕]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 세종대왕과 친구가 됩니다.','이달의 인물 [함께 만든 훈민정음 세종대왕]
한글을 이루고 있는 자음과 모음 24 글자를 알아보며 새로운 지식을 접해봅니다.','이달의 인물 [함께 만든 훈민정음 세종대왕]
동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP005','C0014','P05','이달의 인물 [날아라! 라이트 형제]
동화를 보며, 끈기 있게 노력하여 비행기를 만든 ‘라이트 형제’를 만납니다.
동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [날아라! 라이트 형제]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 라이트 형제와 친구가 됩니다.','이달의 인물 [날아라! 라이트 형제]
라이트 형제가 만든 플라이어호와 오늘날 비행기를 비교해보며 새로운 지식을 접해봅니다.','이달의 인물 [날아라! 라이트 형제]
동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP006','C0014','P06','이달의 인물 [조선의 문을 열다 이성계]
동화를 보며, 새 나라의 질서를 잡은 ‘이성계를 만납니다. 동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [조선의 문을 열다 이성계]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 이성계와 친구가 됩니다.','이달의 인물 [조선의 문을 열다 이성계]
조선을 발전시킨 훌륭한 임금님이 한 일을 알아보며 새로운 지식을 접해봅니다.','이달의 인물 [조선의 문을 열다 이성계]
동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP007','C0014','P07','이달의 인물[탕! 탕! 탕! 안중근]
동화를 보며, 빼앗긴 나라를 위해 만세를 외친 ‘안중근’을 만납니다. 동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[탕! 탕! 탕! 안중근]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 안중근과 친구가 됩니다.','이달의 인물[탕! 탕! 탕! 안중근]
나라를 사랑한 독립 운동가들이 한 일을 알아보며 새로운 지식을 접해봅니다.','이달의 인물[탕! 탕! 탕! 안중근]
동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP008','C0014','P08','이달의 인물 [영웅 나폴레옹]
동화를 보며, 용기 있게 유럽을 정복하고 황제가 된 ‘나폴레옹’을 만납니다. 동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [영웅 나폴레옹]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 나폴레옹과 친구가 됩니다.','이달의 인물 [영웅 나폴레옹]
지도 위에서 나폴레옹이 차지한 유럽 여러 나라를 찾고, 각 나라의 국기를 알아보며 새로운 지식을 접해봅니다.','이달의 인물 [영웅 나폴레옹]
동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP009','C0014','P09','이달의 인물 [가자, 아프리카로! 슈바이처]
동화를 보며, 아프리카에서 나눔을 실천한 ‘슈바이처’를 만납니다. 동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [가자, 아프리카로! 슈바이처]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 슈바이처와 친구가 됩니다.','이달의 인물 [가자, 아프리카로! 슈바이처]
아픈 곳에 따라 가야하는 병원의 종류를 알아보며 새로운 지식을 접해봅니다.','이달의 인물 [가자, 아프리카로! 슈바이처]
동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP010','C0014','P10','이달의 인물 [약속을 지킨 김유신]
동화를 보며, 자신과의 약속을 지켜 훌륭한 장군이 된 ‘김유신’ 을 만납니다. 동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [약속을 지킨 김유신]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 김유신과 친구가 됩니다.','이달의 인물 [약속을 지킨 김유신]
오늘날까지 남아있는 신라시대의 소중한 문화재 알아보며 새로운 지식을 접해봅니다.','이달의 인물 [약속을 지킨 김유신]
동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP011','C0014','P11','이달의 인물 [고마워요 루이 브라유]
동화를 보며, 시각 장애인을 위해 점자를 만든 ‘루이 브라유’를 만납니다. 동화 속 인물의 마음을 알아보고, 인물의 표정과 비슷한 감정을 찾아보는 공감독서 시간을 갖습니다.','이달의 인물 [고마워요 루이 브라유]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 퍼즐게임 등 다양한 놀이를 통해 루이 브라유와 친구가 됩니다.','이달의 인물 [고마워요 루이 브라유]
우리 생활 속에서 점자가 사용된 곳을 알아보며 새로운 지식을 접해봅니다.  ','이달의 인물 [고마워요 루이 브라유]
동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP012','C0014','P12','이달의 인물 [어린이를 사랑한 방정환]
동화를 보며, 어린이를 사랑하고 존중했던 ‘방정환’을 만납니다.동화 속 인물의 마음을 알아보고, 인물의 표정과 비슷한 감정을 찾아보는 공감독서 시간을 갖습니다.','이달의 인물 [어린이를 사랑한 방정환]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 퍼즐게임 등 다양한 놀이를 통해 루이 브라유와 친구가 됩니다.','이달의 인물 [어린이를 사랑한 방정환]
우리나라의 기념일과 국경일에 대해 알아보고, 정확한 날짜를 따라 써보며 새로운 지식을 접해봅니다.','이달의 인물 [어린이를 사랑한 방정환]
동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP013','C0014','P13','이달의 인물 [아버지의 회초리! 김구]
동화를 보며, 아버지에게 효를 실천한 ‘김구’를 만납니다. 동화 속 인물의 마음을 알아보고, 인물의 표정과 비슷한 감정을 찾아보는 공감독서 시간을 갖습니다.','이달의 인물 [아버지의 회초리! 김구]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 퍼즐게임 등 다양한 놀이를 통해 루이 브라유와 친구가 됩니다.','이달의 인물 [아버지의 회초리! 김구]
지식활동보드를 통해 빼앗긴 나라를 되찾기 위한 독립운동에 대해 배워봅시다.','이달의 인물 [아버지의 회초리! 김구]
동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP014','C0014','P14','이달의 인물 [소금행진 간디]
동화를 보며, 소금행진을 하며 나라를 지킨 ‘간디’ 를 만납니다. 동화 속 인물의 마음을 알아보고, 인물의 표정과 비슷한 감정을 찾아보는 공감독서 시간을 갖습니다.
','이달의 인물 [소금행진 간디]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 퍼즐게임 등 다양한 놀이를 통해 간디와 친구가 됩니다.','이달의 인물 [소금행진 간디]
지식활동보드를 통해 인도의 국기, 음식, 문화 등에 대해 알아보며 새로운 지식을 접해봅니다.','이달의 인물 [소금행진 간디]
동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP015','C0014','P15','이달의 인물 [승리의 불꽃 최무선] 동화를 보며 화약을 만든 최무선을 만납니다. 동화 속 인물의 마음을 알아보며 나의 감정을 표현하는 공감독서 활동을 한 후 ''끈기''의 자세를 알아봅니다. 그리고 스토리를 떠올리며 독서골든벨을 함께 풀어 봅니다. ','이달의 인물 [승리의 불꽃 최무선] 동화의 내용을 기억하며 동요를 신나게 불러본 후 다양한 표현놀이 중심의 워크북을 풀며 독후활동을 합니다. 또, 지식활동보드를 통해 최무선이 살았던 고려시대의 왕, 문화재 등의 특징을 알아봅니다.','이달의 인물 [승리의 불꽃 최무선] 이야기 속 최무선이 화포를 만들게 된 과정을 떠올려 본 후 동화 속 그림읽기로 단어를 익히는 한글학습을 합니다. 그리고 카드를 뽑아 질문에 대해 이야기 나누며 자신의 생각을 큰 소리로 말해 봅니다.','이달의 인물 [승리의 불꽃 최무선] 최무선을 만나며 배운 ''끈기''의 약속을 큰 소리로 외치고 선생님과 함께 최무선 관련 연계도서를 읽고 독서활동을 어어갑니다. 놀이활동북 속 퍼즐 완성하기를 통해 끈기를 체험하고, 실제 최무선의 표정과 목소리를 살피며 연극활동을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP016','C0014','P16','이달의 인물 [우주의 비밀 뉴턴] 동화를 통해 우주의 질서를 밝혀낸 뉴턴을 만납니다. 위인이 겪은 일을 통해 동화 속 인물의 마음을 짐작하고, 어떤 마음인지 표현해 보는 공감 독서활동을 한 후 뉴턴의 만유인력의 법칙을 선생님과 함께 알아보고, 독서 골든벨을 풀어봅니다.','이달의 인물 [우주의 비밀 뉴턴] 즐겁게 동요를 불러보며 노랫말을 익히고, 워크북을 통해 동화내용과 연계해 다양한 표현력을 기르는 문제를 해결해 봅니다. 그리고 ''태양계'' 여러 행성들을 배우며 지식활동보드로 지식을 넓힙니다.','이달의 인물 [우주의 비밀 뉴턴] 동화 속 핵심 장면 속 그림-단어를 큰 소리로 말하며 한글과 친해지는 한글놀이 활동을 합니다. 뉴턴과 관련된 다양한 질문에 답하며 자신의 생각을 발표한 후 뉴턴이 만유인력의 법칙을 찾기 위해 어떤 노력을 했는지 이야기 나눕니다.','이달의 인물 [우주의 비밀 뉴턴] 뉴턴을 통해 배운 인성주제 질서를 지켜야 하는 상황에 대해 이야기 나눠보며 주제확장도서를 읽고 독후활동을 합니다. 또, 위인가면을 활용해 직접 위인이 되어본 다음 더 가까이에서 알아갑니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP017','C0014','P17','이달의 인물 [거북선을 만든 이순신]
동화를 보며, 나라를 사랑한 장군 ‘이순신’을 만납니다.
동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [거북선을 만든 이순신]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 이순신과 친구가 됩니다.','이달의 인물 [거북선을 만든 이순신]
이순신이 만든 거북선에 대해 알아보며 새로운 지식을 접해봅니다.','이달의 인물 [거북선을 만든 이순신]
동화 속 중심 단어를 따라 쓰고, 문장으로 장면을 이야기하며 한글을 익히는 시간입니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP018','C0014','P18','이달의 인물[용감한 소녀! 잔다르크]
동화를 보며, 나라를 위해 용기있게 싸운 ‘잔다르크’를 만납니다.
동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [용감한 소녀! 잔다르크]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 잔다르크와 친구가 됩니다.','이달의 인물 [용감한 소녀! 잔다르크]
지식활동보드를 통해 잔다르크의 나라 프랑스에 대해 배워봅시다.','이달의 인물[용감한 소녀! 잔다르크]
동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP019','C0014','P19','이달의 인물[제주도 할머니의 소원! 김만덕]
동화를 보며, 제주도 사람들을 위해 자신의 재산을 나눈 ‘김만덕’을 만납니다. 동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [제주도 할머니의 소원! 김만덕]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 김만덕과 친구가 됩니다.','이달의 인물  [제주도 할머니의 소원! 김만덕]
지식활동보드를 통해 아름다운 섬 제주도에 대해 배워봅시다.','이달의 인물 [제주도 할머니의 소원! 김만덕]
동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP020','C0014','P20','이달의 인물[자유를 위한 약속! 마틴루서킹]
동화를 보며, 흑인의 자유를 위해 약속 운동을 이끌었던 ‘마틴루서킹’을 만납니다.
동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[자유를 위한 약속! 마틴루서킹]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 김만덕과 친구가 됩니다.','이달의 인물[자유를 위한 약속! 마틴루서킹]
지식활동보드를 통해 세계 여러나라에 대해 배워봅시다.','이달의 인물[자유를 위한 약속! 마틴루서킹]
동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP021','C0014','P21','이달의 인물[가난한 사람들의 어머니 테레사 수녀]
동화를 보며, 인도의 가난한 사람들을 보살핀 ‘테레사 수녀’를 만납니다.
동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[가난한 사람들의 어머니 테레사 수녀]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 테레사 수녀와 친구가 됩니다.','이달의 인물[가난한 사람들의 어머니 테레사 수녀]
지식활동보드를 통해 테레사 수녀가 인도의 가난한 사람들을 위해 만든 많은 집을 알아보고 따뜻한 사랑의 마음을 배워봅니다.','이달의 인물[가난한 사람들의 어머니 테레사 수녀]
동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP022','C0014','P22','이달의 인물[링컨, 미국을 바꾼 대통령] 동화를 보며, 흑인이 존중받는 세상을 만든 미국의 대통령 ‘링컨’을 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[링컨, 미국을 바꾼 대통령] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 링컨과 친구가 됩니다.','이달의 인물[링컨, 미국을 바꾼 대통령] 지식활동보드를 보며 자유의 나라 미국의 상징인 자유의 여신상의 이모저모를 살펴보고 함께 이야기 나눕니다.','이달의 인물[링컨, 미국을 바꾼 대통령] 동화 장면 속 그림읽기를 통해 단어를 듣고, 말하는 연습을 한 후 한글을 익혀봅니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP023','C0014','P23','이달의 인물[이야기를 만든 효자 김만중] 동화를 보며, 어머니를 사랑하는 마음을 담아 이야기를 만든 ‘김만중’을 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[이야기를 만든 효자 김만중] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 김만중과 친구가 됩니다.','이달의 인물[이야기를 만든 효자 김만중] 지식활동보드를 통해 가족나무에 있는 가족과 친척을 부르는 이름을 알아봅니다.','이달의 인물[이야기를 만든 효자 김만중] 동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP024','C0014','P24','이달의 인물[수원화성의 비밀 정조,정약용] 동화를 보며, 협력으로 수원화성을 만든 ‘정조,정약용’을 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[수원화성의 비밀 정조,정약용] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 정조,정약용과 친구가 됩니다.','이달의 인물[수원화성의 비밀 정조,정약용] 지식활동보드를 통해 임금님과 그 가족이 사는 조선의 궁궐에 대해 알아봅니다.','이달의 인물[수원화성의 비밀 정조, 정약용] 동화 장면 속 그림읽기를 통해 단어를 듣고, 말하는 연습을 한 후 한글을 익혀봅니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP025','C0014','P25','이달의 인물[위대한 음악가 베토벤] 동화를 보며, 끈기있게 노력해 훌륭한 음악가가 된 ‘베토벤’을 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.
','이달의 인물[이야기를 만든 효자 김만중] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 김만중과 친구가 됩니다.','이달의 인물[위대한 음악가 베토벤] 지식활동보드를 통해 멋지고 아름다운 소리를 내는 악기의 종류를 알아봅니다.','이달의 인물[이야기를 만든 효자 김만중] 동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP026','C0014','P26','이달의 인물[바다의 왕 장보고] 동화를 보며, 바다의 질서를 바로잡은 ‘장보고’를 만납니다.동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[바다의 왕 장보고] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 장보고와 친구가 됩니다.','이달의 인물[바다의 왕 장보고] 지식활동보드를 통해 우리나라와 중국, 일본으로 가는 바닷길을 재미있게 꾸며봅니다.','이달의 인물[바다의 왕 장보고] 동화 장면 속 그림읽기를 통해 단어를 듣고, 말하는 연습을 한 후 한글을 익혀봅니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP027','C0014','P27','이달의 인물[뜨거운 만세 유관순] 동화를 보며, 나라를 되찾기 위해 만세운동을 한 ‘유관순’을 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[뜨거운 만세 유관순] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 유관순과 친구가 됩니다.','이달의 인물[뜨거운 만세 유관순] 지식활동보드를 통해 우리나라의 국경일, 기념일에 태극기를 올바르게 다는 방법을 알아봅니다.','이달의 인물[뜨거운 만세 유관순] 동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP028','C0014','P28','이달의 인물[떠나자! 콜럼버스] 동화를 보며, 신대륙을 발견한 용기 있는 ‘콜럼버스’를 만납니다.동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다. ','이달의 인물[떠나자! 콜럼버스] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 콜럼버스와 친구가 됩니다.','이달의 인물[떠나자! 콜럼버스] 지식활동보드를 통해 5대양 6대륙의 위치를 알아보고, 우리가 살고 있는 아시아대륙과 신대륙인 아메리카 대륙을 찾아봅니다.','이달의 인물[떠나자! 콜럼버스] 동화 장면 속 그림읽기를 통해 단어를 듣고, 말하는 연습을 한 후 한글을 익혀봅니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP029','C0014','P29','이달의 인물[컴퓨터 천재, 빌 게이츠] 동화를 보며, 컴퓨터 프로그램을 만들고 부자가 되어 나눔을 실천한 ‘빌 게이츠’를 만납니다.동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다. ','이달의 인물[컴퓨터 천재, 빌 게이츠] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 빌 게이츠와 친구가 됩니다.','이달의 인물[컴퓨터 천재, 빌 게이츠] 지식활동보드를 통해 척척박사 컴퓨터를 구성하는 각 부분의 이름과 하는 일을 알아봅니다.','이달의 인물[컴퓨터 천재, 빌 게이츠] 동화 장면 속 그림읽기를 통해 단어를 듣고, 말해보며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'KP030','C0014','P30','이달의 인물[노벨상에 담긴 약속, 노벨] 동화를 보며, 다이너마이트를 발명하고 전 세계의 평화와 행복을 위해 약속을 지킨 ‘노벨’을 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다. ','이달의 인물[노벨상에 담긴 약속, 노벨] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 노벨과 친구가 됩니다.','이달의 인물[노벨상에 담긴 약속, 노벨] 지식활동보드를 통해 세계 평화를 위해 노력한 노벨평화상을 받은 인물에 대해 함께 알아봅니다.','이달의 인물[노벨상에 담긴 약속, 노벨] 동화 장면 속 그림읽기를 통해 단어를 듣고, 말하는 연습을 한 후 한글을 익혀봅니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP001','C0015','P01','이달의 인물 [따뜻한 마음 허준 선생님]
동화를 보며, 환자를 배려한 조선의 의사 ‘허준’을 만납니다.
동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [따뜻한 마음 허준 선생님]
동화 속 중심 단어를 따라 쓰고, 문장으로 장면을 이야기하며 한글을 익히는 시간입니다. ','이달의 인물 [따뜻한 마음 허준 선생님]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 허준과 친구가 됩니다.','이달의 인물 [따뜻한 마음 허준 선생님]
허준이 쓴 최고의 의학책 동의보감에 대해 알아보며 새로운 지식을 접해봅니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP002','C0015','P02','이달의 인물 [동물은 내 친구 제인구달]
동화를 보며, 침팬지를 존중한 동물학자 ‘제인구달’을 만납니다.
동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.
','이달의 인물 [동물은 내 친구 제인구달]
동화 속 중심 단어를 따라 쓰고, 문장으로 장면을 이야기하며 한글을 익히는 시간입니다.
','이달의 인물 [동물은 내 친구 제인구달]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 제인구달과 친구가 됩니다.
','이달의 인물 [동물은 내 친구 제인구달]
지도에서 아프리카를 찾고, 신비의 땅 아프리카에 대해 알아보며 새로운 지식을 접해봅니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP003','C0015','P03','이달의 인물 [지갑 속의 효자 이이]
동화를 보며, 어머니를 사랑한 효자 ‘이이’를 만납니다.
동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [지갑 속의 효자 이이]
동화 속 중심 단어를 따라 쓰고, 문장으로 장면을 이야기하며 한글을 익히는 시간입니다. ','이달의 인물 [지갑 속의 효자 이이]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 이이와 친구가 됩니다.','이달의 인물 [지갑 속의 효자 이이]
우리나라 동전과 지폐 속 주인공에 대해 알아보며 새로운 지식을 접해봅니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP004','C0015','P04','이달의 인물 [함께 만든 훈민정음 세종대왕]
