INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP013','C0015','P13','이달의 인물 [아버지의 회초리! 김구]
동화를 보며, 아버지에게 효를 실천한 ‘김구’를 만납니다. 동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [아버지의 회초리! 김구]
