INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP014','C0015','P14','이달의 인물 [소금행진 간디]
동화를 보며, 소금행진을 하며 나라를 지킨 ‘간디’ 을 만납니다. 동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [소금행진 간디]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 간디와 친구가 됩니다.','이달의 인물 [소금행진 간디]
지식활동보드를 통해 지식활동보드를 통해 인도의 국기, 음식, 문화 등에 대해 알아보며 새로운 지식을 접해봅니다.','이달의 인물 [소금행진 간디]
동화 속 중심 단어를 따라 쓰고, 문장으로 장면을 이야기하며 한글을 익히는 시간입니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP015','C0015','P15','이달의 인물 [승리의 불꽃 최무선] 동화 스토리를 생각하며 고려의 발명가 ‘최무선’을 만납니다. 동화 속 인물의 마음을 알아보고, 상황 속에 감정이입을 해보며 내 마음을 표현하는 공감독서 시간을 갖습니다. 또, 최무선의 업적을 정리한 다음 동화 속 퀴즈를 큰소리로 외치며 독서골든벨을 함께 합니다.  ','이달의 인물 [승리의 불꽃 최무선] 동요를 함께 부르며 노랫말을 익힌 후 동화와 생활을 연계한 통합 놀이 워크북을 함께 풀어봅니다. 그리고 고려를 세운 왕, 고려의 문화를 알아보는 지식활동보드를 통해 배경지식을 넓힙니다.','이달의 인물 [승리의 불꽃 최무선] 동화를 떠올리며 중심단어를 넣어 장면을 말하고 단어를 익히는 한글놀이 활동을 합니다. 최무선과 관련된 다양한 생각을 나누는 생각말하기로 발표를 한 후 최무선이 화약을 만들기 위해 어떤 노력을 했는지 이야기 나누며 생각을 키워갑니다. ','이달의 인물 [승리의 불꽃 최무선] 최무선을 통해 생활 속에서 실천할 수 있는 끈기의 자세를 말해보며 최무선과 연계된 주제확장도서를 읽고 내용을 정리해 봅니다. 놀이활동북으로 친구들과 체험하며 끈기를 익혀보고, 상황에 맞는 표정과 목소리로 연극을 하며 인물을 더 가까이에서 이해합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP016','C0015','P16','이달의 인물 [우주의 비밀 뉴턴] 동화를 통해 우주의 질서를 밝혀낸 뉴턴을 만납니다. 위인이 겪은 일을 통해 동화 속 인물의 마음을 알아보는 공감독서 활동을 한 후 뉴턴의 만유인력의 법칙을 선생님과 함께 알아본 다음 동화내용을 퀴즈로 만나며 독서 골든벨을 풀어봅니다.','이달의 인물 [우주의 비밀 뉴턴] 즐겁게 동요를 불러보며 노랫말을 익히고, 워크북을 통해 동화내용과 연계해 다양한 유형의 문제를 해결해 봅니다. 그리고 우주에 대한 관심을 확장해 ''태양계'' 행성들을 배우며 지식활동보드로 지식을 넓힙니다.','이달의 인물 [우주의 비밀 뉴턴] 동화 속 중심단어를 익히며 한글과 친해지는 한글익히기 활동을 합니다. 뉴턴과 관련된 다양한 질문에 답하며 자신의 생각을 발표한 후 뉴턴이 만유인력의 법칙을 찾기 위해 노력한 과정에 대해 이야기 나눕니다.','이달의 인물 [우주의 비밀 뉴턴] 뉴턴을 통해 배운 인성주제 질서를 생활 속에서 지켜야 하는 상황에 대해 이야기 나눠보며 주제확장도서를 읽고 독후활동을 합니다. 체험 속에서 즐기는 놀이활동을 통해 질서의 중요성을 배운 후, 위인가면을 활용해 직접 위인이 되어본 다음 더 가까이에서 알아갑니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP017','C0015','P17','이달의 인물 [거북선을 만든 이순신]
동화를 보며, 나라는 사랑한 장군 ‘이순신’을 만납니다.
동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [거북선을 만든 이순신]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 이순신과 친구가 됩니다.','이달의 인물 [거북선을 만든 이순신]
이순신이 만든 거북선에 대해 알아보며 새로운 지식을 접해봅니다.','이달의 인물 [거북선을 만든 이순신]
동화 속 중심 단어를 따라 쓰고, 문장으로 장면을 이야기하며 한글을 익히는 시간입니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP018','C0015','P18','이달의 인물[용감한 소녀! 잔다르크]
동화를 보며 나라를 위해 용기있게 싸운 ‘잔다르크’를 만납니다.
동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [용감한 소녀! 잔다르크]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 잔다르크와 친구가 됩니다.','이달의 인물 [용감한 소녀! 잔다르크]
지식활동보드를 통해 잔다르크의 나라 프랑스에 대해 배워봅시다.','이달의 인물[용감한 소녀! 잔다르크]
동화 속 중심 단어를 따라 쓰고, 문장으로 장면을 이야기하며 한글을 익히는 시간입니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP019','C0015','P19','이달의 인물[제주도 할머니의 소원! 김만덕]
동화를 보며, 제주도 사람들을 위해 자신의 재산을 나눈 ‘김만덕’을 만납니다.
