INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP020','C0015','P20','이달의 인물[자유를 위한 약속! 마틴루서킹]
동화를 보며, 흑인의 자유를 위해 약속 운동을 이끌었던 ‘마틴루서킹’을 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다','이달의 인물[자유를 위한 약속! 마틴루서킹]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 김만덕과 친구가 됩니다.','이달의 인물[자유를 위한 약속! 마틴루서킹]
지식활동보드를 통해 세계 여러나라에 대해 배워봅시다.','이달의 인물[자유를 위한 약속! 마틴루서킹]
