INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP021','C0015','P21','이달의 인물[가난한 사람들의 어머니 테레사 수녀]
동화를 보며, 인도의 가난한 사람들을 보살피고 배려한 ‘테레사 수녀’를 만납니다.
동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[가난한 사람들의 어머니 테레사 수녀]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 테레사 수녀와 친구가 됩니다.','이달의 인물[가난한 사람들의 어머니 테레사 수녀]
지식활동보드를 통해 테레사 수녀가 인도의 가난한 사람들을 위해 만든 많은 집을 알아보고 따뜻한 배려의 마음을 배워봅니다.','이달의 인물[가난한 사람들의 어머니 테레사 수녀]
동화 속 중심 단어를 따라 쓰고, 문장으로 장면을 이야기하며 한글을 익히는 시간입니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP022','C0015','P22','이달의 인물[링컨, 미국을 바꾼 대통령] 동화를 보며, 흑인이 존중받는 세상을 만든 미국의 16대 대통령 ‘링컨’을 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[링컨, 미국을 바꾼 대통령] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 링컨과 친구가 됩니다.','이달의 인물[링컨, 미국을 바꾼 대통령] 지식활동보드를 보며 자유의 나라 미국의 상징인 자유의 여신상의 이모저모를 살펴보고 함께 이야기 나눕니다.','이달의 인물[링컨, 미국을 바꾼 대통령] 동화 속 중심 단어를 따라 쓰고, 문장으로 장면을 이야기하며 한글을 익히는 시간입니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP023','C0015','P23','이달의 인물[이야기를 만든 효자 김만중] 동화를 보며, 어머니를 사랑하는 마음을 담아 이야기를 만든 ‘김만중’을 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[이야기를 만든 효자 김만중] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 김만중과 친구가 됩니다.','이달의 인물[이야기를 만든 효자 김만중] 지식활동보드를 통해 가계도를 살펴보며 가족과 친척을 부르는 이름을 알아봅니다.','이달의 인물[이야기를 만든 효자 김만중] 동화 속 중심 단어를 따라 쓰고, 문장으로 장면을 이야기하며 한글을 익히는 시간입니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP024','C0015','P24','이달의 인물[수원화성의 비밀 정조,정약용] 동화를 보며, 협력으로 수원화성을 만든 ‘정조,정약용’을 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[수원화성의 비밀 정조,정약용] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 정조,정약용과 친구가 됩니다.','이달의 인물[수원화성의 비밀 정조,정약용] 지식활동보드를 통해 임금님과 그 가족이 사는 조선의 궁궐에 대해 알아봅니다.','이달의 인물[수원화성의 비밀 정조, 정약용] 동화 속 중심 단어를 따라 쓰고, 문장으로 장면을 이야기하며 한글을 익히는 시간입니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP025','C0015','P25','이달의 인물[위대한 음악가 베토벤] 동화를 보며, 장애를 이겨내기 위해 끈기있게 노력한 음악가 ‘베토벤’을 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[위대한 음악가 베토벤] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 베토벤과 친구가 됩니다.','이달의 인물[위대한 음악가 베토벤] 지식활동보드를 통해 베토벤이 사랑한 악기를 종류별로 분류해 봅니다.','이달의 인물[위대한 음악가 베토벤] 동화 속 중심 단어를 따라 쓰고, 문장으로 장면을 이야기하며 한글을 익히는 시간입니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP026','C0015','P26','이달의 인물[바다의 왕 장보고] 동화를 보며, 바다의 질서를 바로잡은 ‘장보고’를 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[바다의 왕 장보고] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 장보고와 친구가 됩','이달의 인물[바다의 왕 장보고] 지식활동보드를 통해 장보고가 지킨 우리나라와 중국, 일본으로 가는 바닷길을 알아봅니다.','이달의 인물[바다의 왕 장보고] 동화 속 중심 단어를 따라 쓰고, 문장으로 장면을 이야기하며 한글을 익히는 시간입니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP027','C0015','P27','이달의 인물[뜨거운 만세 유관순] 동화를 보며, 일본에게 빼앗긴 나라를 되찾기 위해 만세운동을 한 ‘유관순’을 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[뜨거운 만세 유관순] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 유관순과 친구가 됩니다.','이달의 인물[뜨거운 만세 유관순] 지식활동보드를 통해 우리나라의 국경일, 기념일을 알아보고 태극기를 올바르게 다는 방법을 배워봅니다.','이달의 인물[뜨거운 만세 유관순] 동화 속 중심 단어를 따라 쓰고, 문장으로 장면을 이야기하며 한글을 익히는 시간입니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP028','C0015','P28','이달의 인물[떠나자! 콜럼버스] 동화를 보며, 신대륙을 발견한 용기 있는 ‘콜럼버스’를 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다. ','이달의 인물[떠나자! 콜럼버스] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 콜럼버스와 친구가 됩니다.','이달의 인물[떠나자! 콜럼버스] 지식활동보드를 통해 5대양 6대륙의 위치를 알아보고, 우리가 살고 있는 아시아대륙과 신대륙인 아메리카 대륙을 찾아봅니다.','이달의 인물[떠나자! 콜럼버스] 동화 속 중심 단어를 따라 쓰고, 문장으로 장면을 이야기하며 한글을 익히는 시간입니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP029','C0015','P29','이달의 인물[컴퓨터 천재, 빌 게이츠] 동화를 보며, 컴퓨터 프로그램을 만들고 부자가 되어 나눔을 실천한 ‘빌 게이츠’를 만납니다.동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다. ','이달의 인물[컴퓨터 천재, 빌 게이츠] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 빌 게이츠와 친구가 됩니다.','이달의 인물[컴퓨터 천재, 빌 게이츠] 지식활동보드를 통해 척척박사 컴퓨터를 구성하는 각 부분의 이름과 하는 일을 알아봅니다.','이달의 인물[컴퓨터 천재, 빌 게이츠] 동화 속 중심 단어를 따라 쓰고, 문장으로 장면을 이야기하며 한글을 익히는 시간입니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'MP030','C0015','P30','이달의 인물[노벨상에 담긴 약속, 노벨] 동화를 보며, 다이너마이트를 발명하고 전 세계의 평화와 행복을 위해 약속을 지킨 ‘노벨’을 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다. ','이달의 인물[노벨상에 담긴 약속, 노벨] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 노벨과 친구가 됩니다.','이달의 인물[노벨상에 담긴 약속, 노벨] 지식활동보드를 통해 세계 평화를 위해 노력한 노벨평화상을 받은 인물에 대해 함께 알아봅니다.','이달의 인물[노벨상에 담긴 약속, 노벨] 동화 속 중심 단어를 따라 쓰고, 문장으로 장면을 이야기하며 한글을 익히는 시간입니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP001','C0015','P01','이달의 인물 [따뜻한 마음 허준 선생님]
동화 전체 스토리를 파악하며 환자를 배려한 조선의 의사 ‘허준’을 만납니다.
동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [따뜻한 마음 허준 선생님]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 주도적인 놀이학습을 통해 허준을 깊이 있게 이해합니다.','이달의 인물 [따뜻한 마음 허준 선생님]
허준이 쓴 최고의 의학책 동의보감에 대해 알아보며 옛날과 오늘날의 의사를 비교해 봅니다.
','이달의 인물 [따뜻한 마음 허준 선생님]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP002','C0015','P02','이달의 인물 [동물은 내 친구 제인구달]
동화 전체 스토리를 파악하며 침팬지를 존중한 동물학자 ‘제인구달’ 을 만납니다.
동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [동물은 내 친구 제인구달]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 주도적인 놀이학습을 통해 제인구달을 깊이 있게 이해합니다.','이달의 인물 [동물은 내 친구 제인구달]
지도에서 아프리카를 찾고, 신비의 땅 아프리카에 대해 알아보며 동물존중의 방법에 대해 이야기 나눕니다.','이달의 인물 [동물은 내 친구 제인구달]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP003','C0015','P03','이달의 인물 [지갑 속의 효자 이이]
동화 전체 스토리를 파악하며 어머니를 사랑한 효자 ‘이이’를 만납니다.
동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [지갑 속의 효자 이이]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 주도적인 놀이학습을 통해 이이를 깊이 있게 이해합니다.','이달의 인물 [지갑 속의 효자 이이]
우리나라 동전과 지폐 속 인물을 알아보며 우리나라 돈의 가치에 대해 이야기 나누어 봅니다.','이달의 인물 [지갑 속의 효자 이이]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP004','C0015','P04','이달의 인물 [함께 만든 훈민정음 세종대왕]
동화 전체 스토리를 파악하며 신하들과 협력하여 한글을 만든 ‘세종대왕’을 만납니다.
동화 속 인물의 마음을 이해하고 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [함께 만든 훈민정음 세종대왕]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 주도적인 놀이학습을 통해 세종대왕을 깊이 있게 이해합니다. ','이달의 인물 [함께 만든 훈민정음 세종대왕]
한글을 이루고 있는 자음과 모음 24 글자를 알아보며 한글의 소중함에 대해 생각해 봅니다.','이달의 인물 [함께 만든 훈민정음 세종대왕]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP005','C0015','P05','이달의 인물 [날아라! 라이트 형제]
동화 전체 스토리를 파악하며, 끈기 있게 노력하여 비행기를 만든 ‘라이트 형제’를 만납니다.
동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [날아라! 라이트 형제]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 라이트 형제와 친구가 됩니다.','이달의 인물 [날아라! 라이트 형제]
라이트 형제가 만든 플라이어호와 오늘날 비행기를 비교해보며 새로운 지식을 접해봅니다.','이달의 인물 [날아라! 라이트 형제]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP006','C0015','P06','이달의 인물 [조선의 문을 열다 이성계]
동화 전체 스토리를 파악하며, 새 나라의 질서를 잡은 ‘이성계를 만납니다. 동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [조선의 문을 열다 이성계]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 이성계와 친구가 됩니다.','이달의 인물 [조선의 문을 열다 이성계]
조선을 발전시킨 훌륭한 임금님이 한 일을 알아보며 새로운 지식을 접해봅니다.','이달의 인물 [조선의 문을 열다 이성계]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP007','C0015','P07','이달의 인물[탕! 탕! 탕! 안중근]
동화 전체 스토리를 파악하며, 빼앗긴 나라를 위해 만세를 외친 ‘안중근’을 만납니다. 동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.
','이달의 인물[탕! 탕! 탕! 안중근]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 안중근과 친구가 됩니다.
','이달의 인물[탕! 탕! 탕! 안중근]
나라를 사랑한 독립 운동가들이 한 일을 알아보며 새로운 지식을 접해봅니다.','이달의 인물[탕! 탕! 탕! 안중근]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP008','C0015','P08','이달의 인물 [영웅 나폴레옹]
동화 전체 스토리를 파악하며, 용기 있게 유럽을 정복하고 황제가 된 ‘나폴레옹’을 만납니다. 동화 속 인물의 마음을 알아보고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [영웅 나폴레옹]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 나폴레옹과 친구가 됩니다.','이달의 인물 [영웅 나폴레옹]
지도 위에서 나폴레옹이 차지한 유럽 여러 나라를 찾고, 각 나라의 국기를 알아보며 새로운 지식을 접해봅니다.','이달의 인물 [영웅 나폴레옹]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP009','C0015','P09','이달의 인물 [가자, 아프리카로! 슈바이처]
동화 전체 스토리를 파악하며 아프리카에서 나눔을 실천한 ‘슈바이처’를 만납니다.
동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [가자, 아프리카로! 슈바이처]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 주도적인 놀이학습을 통해 슈바이처를 깊이 있게 이해합니다.','이달의 인물 [가자, 아프리카로! 슈바이처]
아픈 곳에 따라 가야하는 병원의 종류를 알아보며 자신의 경험을 이야기해 봅니다.','이달의 인물 [가자, 아프리카로! 슈바이처]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP010','C0015','P10','이달의 인물 [약속을 지킨 김유신]
동화 전체 스토리를 파악하며 자신과의 약속을 지켜 장군이 된 ‘김유신’을 만납니다.
동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [약속을 지킨 김유신]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 주도적인 놀이학습을 통해 김유신을 깊이 있게 이해합니다.','이달의 인물 [약속을 지킨 김유신]
오늘날까지 남아있는 신라시대의 소중한 문화재에 대해 알아보며 문화재를 대하는 올바른 자세에 대해 이야기 나누어 봅니다.
','이달의 인물 [약속을 지킨 김유신]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP011','C0015','P11','이달의 인물 [고마워요 루이 브라유]
동화 전체 스토리를 파악하며 시각 장애인을 위해 점자를 만든 ‘루이 브라유’를 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [고마워요 루이 브라유]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 주도적인 놀이학습을 통해 루이 브라유를 깊이 있게 이해합니다.','이달의 인물 [고마워요 루이 브라유]
생활 속에서 점자가 사용된 곳을 알아보며 시각 장애인의 삶에 대해 이야기 나누어 봅니다. ',' 이달의 인물 [고마워요 루이 브라유]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP012','C0015','P12','이달의 인물 [어린이를 사랑한 방정환]
동화 전체 스토리를 파악하며 어린이를 사랑하고 존중했던 ‘방정환’을 만납니다.
동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [어린이를 사랑한 방정환]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 주도적인 놀이학습을 통해 방정환을 깊이 있게 이해합니다.','이달의 인물 [어린이를 사랑한 방정환]
우리나라의 기념일과 국경일에 대해 알아보고, 날짜를 따라 써보며 의미를 되새겨 봅니다. ','이달의 인물 [어린이를 사랑한 방정환]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP013','C0015','P13','이달의 인물[아버지의 회초리! 김구]
동화 전체 스토리를 파악하며 아버지에게 효를 실천한 ‘김구’를 만납니다.
동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [아버지의 회초리! 김구]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 김구와 친구가 됩니다.','이달의 인물 [아버지의 회초리! 김구]
지식활동보드를 통해 빼앗긴 나라를 되찾기 위한 독립운동에 대해 배워봅시다.','이달의 인물 [아버지의 회초리! 김구]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP014','C0015','P14','이달의 인물 [소금행진 간디]
동화 전체 스토리를 파악하며 인도를 위해 독립을 실천한 ‘간디’를 만납니다.
동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [소금행진 간디]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 간디와 친구가 됩니다.','이달의 인물 [소금행진 간디]
지식활동보드를 통해 지식활동보드를 통해 인도의 국기, 음식, 문화 등에 대해 알아보며 새로운 지식을 접해봅니다.','이달의 인물 [아버지의 회초리! 김구]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP015','C0015','P15','이달의 인물 [승리의 불꽃 최무선] 동화를 ''기-승-전-결'' 흐름에 따라 스토리를 이해하며 고려의 발명가 최무선을 만납니다. 동화 속 인물의 마음을 이해하고, 비슷한 경험을 떠올려보며 공감독서 활동을 합니다. 그리고 업적을 이해한 후 독서 골든벨에 참여해 퀴즈를 통해 스토리를 정리합니다.','이달의 인물 [승리의 불꽃 최무선]을 통해 노랫말을 익히며 동요를 부르고, 다양한 지식을 넓히는 동화연계 문제를 풀어보며 독서의 깊이를 만듭니다. 그리고 최무선이 화약을 만들기 위한 과정을 돌아보며 최무선이 살던 나라 고려의 왕과 문화적 특징을 알아보는 지식활동보드를 통해 역사에 대한 이해를 넓혀갑니다.','이달의 인물 [승리의 불꽃 최무선] 최무선이 화약을 만든 과정을 떠올리며 끈기와 연계해 주제에 대해 이야기 나눈 후 중심단어를 넣어 중심문장을 만들어보는 한글학습 시간을 갖습니다. 최무선과 관련된 질문에 대해 답하며 내 생각과 친구들의 생각을 비교해 봅니다. ','이달의 인물 [승리의 불꽃 최무선] 최무선을 통해 배운 ''끈기''를 실천한 경험을 발표하고, 최무선 주제확장 도서를 함께 읽고 최무선과 연계해 독후활동을 어어갑니다. 그리고 모둠별로 끈기와 인내를 체험하는 놀이활동북을 함께한 후 역할을 나눠 상황에 맞는 알맞은 목소리와 표정으로 연극활동을 합니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP016','C0015','P16','이달의 인물 [우주의 비밀 뉴턴] 기승전결 동화 스토리 전체를 파악하며 동화를 통해 영국의 과학자 뉴턴을 만납니다. 동화 속 인물이 처한 상황을 이해하고 마음에 공감하는 공감독서활동을 한 후 뉴턴의 업적을 상세하게 정리해 봅니다. 그리고 독서골든벨을 통해 퀴즈로 동화를 정리하며 스토리를 정리합니다.','이달의 인물 [우주의 비밀 뉴턴] 동요를 부르며 노랫말을 기억한 후 동화와 연계해 지식을 넓히는 통합 놀이 워크북을 풀며 문제해결력을 기릅니다. 그리고 우주에 대한 관심을 확장해 ''태양계'' 행성들을 배우며 지식활동보드로 지식을 넓힙니다.','이달의 인물 [우주의 비밀 뉴턴] 동화 장면과 연계해 기초 읽기, 기초쓰기를 다지는 한글학습을 합니다. 뉴턴과 관련된 다양한 질문에 답하며 자신의 생각을 발표한 후 뉴턴이 만유인력의 법칙을 찾기 위해 노력한 과정에 대해 이야기 나눕니다.','이달의 인물 [우주의 비밀 뉴턴] 뉴턴을 통해 생활 속에서 질서를 지켜야 하는 상황을 말해보고 주제연계 확장도서를 읽고 퀴즈를 풀며 독후활동을 합니다. 위인가면을 활용해 동화 속 한 장면을 연극활동으로 체험해보며 다양한 놀이활동을 통해 학습의 경험을 넓힙니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP017','C0015','P17','이달의 인물 [거북선을 만든 이순신]
동화 전체 스토리를 파악하며 나라를 사랑한 장군 ‘이순신’을 만납니다.
동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [거북선을 만든 이순신]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 주도적인 놀이학습을 통해 이순신의 나라 사랑을 깊이 있게 이해합니다.','이달의 인물 [거북선을 만든 이순신]
일본을 무찌른 거북선을 통해 임진왜란에서 승리한 이순신을 알아봅니다.
','이달의 인물 [거북선을 만든 이순신]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP018','C0015','P18','이달의 인물[용감한 소녀! 잔다르크]
동화 전체 스토리를 파악하며 나라를 위해 용기있게 싸운 ‘잔다르크’를 만납니다.
동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [용감한 소녀! 잔다르크]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 잔다르크와 친구가 됩니다.','이달의 인물 [용감한 소녀! 잔다르크]
지식활동보드를 통해 잔다르크의 나라 프랑스에 대해 배워봅시다.','이달의 인물[용감한 소녀! 잔다르크]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP019','C0015','P19','이달의 인물[제주도 할머니의 소원! 김만덕]
동화 전체 스토리를 파악하며 제주도 사람들을 위해 자신의 재산을 나눈 ‘김만덕’을 만납니다.
동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물 [제주도 할머니의 소원! 김만덕]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 김만덕과 친구가 됩니다.','이달의 인물  [제주도 할머니의 소원! 김만덕]
지식활동보드를 통해 아름다운 섬 제주도에 대해 배워봅시다.','이달의 인물 [제주도 할머니의 소원! 김만덕]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP020','C0015','P20','이달의 인물[자유를 위한 약속! 마틴루서킹]
동화 전체 스토리를 파악하며 흑인의 자유를 위해 약속 운동을 이끌었던 ‘마틴루서킹’을 만납니다.
동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[자유를 위한 약속! 마틴루서킹]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극등 다양한 놀이를 통해 김만덕과 친구가 됩니다.','이달의 인물[자유를 위한 약속! 마틴루서킹]
지식활동보드를 통해 세계 여러나라에 대해 배워봅시다.','이달의 인물[자유를 위한 약속! 마틴루서킹]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP021','C0015','P21','이달의 인물[가난한 사람들의 어머니 테레사 수녀]
동화 전체 스토리를 파악하며 인도의 가난한 사람들을 보살피고 배려한 ‘테레사 수녀’를 만납니다.
동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[가난한 사람들의 어머니 테레사 수녀]
즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 테레사 수녀와 친구가 됩니다.','이달의 인물[가난한 사람들의 어머니 테레사 수녀]
지식활동보드를 통해 테레사 수녀가 인도의 가난한 사람들을 위해 만든 많은 집을 알아보고 따뜻한 배려의 마음을 배워봅니다.','이달의 인물[가난한 사람들의 어머니 테레사 수녀]
동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP022','C0015','P22','이달의 인물[링컨, 미국을 바꾼 대통령] 동화 전체 스토리를 파악하며 흑인이 존중받는 세상을 만든 미국의 16대 대통령 ‘링컨’을 만납니다.동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[링컨, 미국을 바꾼 대통령] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 링컨과 친구가 됩니다.','이달의 인물[링컨, 미국을 바꾼 대통령] 지식활동보드를 보며 자유의 나라 미국의 상징인 자유의 여신상의 이모저모를 살펴보고 함께 이야기 나눕니다.','이달의 인물[링컨, 미국을 바꾼 대통령] 동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP023','C0015','P23','이달의 인물[이야기를 만든 효자 김만중] 동화 전체 스토리를 파악하며 어머니를 사랑하는 마음을 담아 이야기를 만든 ‘김만중’을 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[이야기를 만든 효자 김만중] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 김만중과 친구가 됩니다.','이달의 인물[이야기를 만든 효자 김만중] 지식활동보드를 통해 가계도를 살펴보며 가족과 친척을 부르는 이름을 알아봅니다.','이달의 인물[이야기를 만든 효자 김만중] 동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP024','C0015','P24','이달의 인물[수원화성의 비밀 정조,정약용] 동화 전체 스토리를 파악하며 협력으로 수원화성을 만든 ‘정조,정약용’을 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[수원화성의 비밀 정조,정약용] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 정조,정약용과 친구가 됩니다.','이달의 인물[수원화성의 비밀 정조,정약용] 지식활동보드를 통해 임금님과 그 가족이 사는 조선의 궁궐에 대해 알아봅니다.','이달의 인물[수원화성의 비밀 정조, 정약용] 동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP025','C0015','P25','이달의 인물[위대한 음악가 베토벤] 동화 전체 스토리를 파악하며 장애를 이겨내기 위해 끈기있게 노력한 음악가 ‘베토벤’을 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[위대한 음악가 베토벤] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 베토벤과 친구가 됩니다.','이달의 인물[위대한 음악가 베토벤] 지식활동보드를 통해 베토벤이 사랑한 악기를 종류별로 분류해 봅니다.','이달의 인물[위대한 음악가 베토벤] 동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP026','C0015','P26','이달의 인물[바다의 왕 장보고] 동화 전체 스토리를 파악하며 바다의 질서를 바로잡은 ‘장보고’를 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[바다의 왕 장보고] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 장보고와 친구가 됩니다.','이달의 인물[바다의 왕 장보고] 지식활동보드를 통해 장보고가 지킨 우리나라와 중국, 일본으로 가는 바닷길을 알아봅니다.','이달의 인물[바다의 왕 장보고] 동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP027','C0015','P27','이달의 인물[뜨거운 만세 유관순] 동화 전체 스토리를 파악하며 일본에게 빼앗긴 나라를 되찾기 위해 만세운동을 한 ‘유관순’을 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다.','이달의 인물[뜨거운 만세 유관순] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 유관순과 친구가 됩니다.','이달의 인물[뜨거운 만세 유관순] 지식활동보드를 통해 우리나라의 국경일, 기념일을 알아보고 태극기를 올바르게 다는 방법을 배워봅니다.','이달의 인물[뜨거운 만세 유관순] 동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP028','C0015','P28','이달의 인물[떠나자! 콜럼버스] 동화 전체 스토리를 파악하며 신대륙을 발견한 용기 있는 ‘콜럼버스’를 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다. ','이달의 인물[떠나자! 콜럼버스] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 콜럼버스와 친구가 됩니다.','이달의 인물[떠나자! 콜럼버스] 지식활동보드를 통해 5대양 6대륙의 위치를 알아보고, 우리가 살고 있는 아시아대륙과 신대륙인 아메리카 대륙을 찾아봅니다.','이달의 인물[떠나자! 콜럼버스] 동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP029','C0015','P29','이달의 인물[컴퓨터 천재, 빌 게이츠] 동화 전체 스토리를 파악하며 컴퓨터 프로그램을 만들고 부자가 되어 나눔을 실천한 ‘빌 게이츠’를 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다. ','이달의 인물[컴퓨터 천재, 빌 게이츠] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 빌 게이츠와 친구가 됩니다.','이달의 인물[컴퓨터 천재, 빌 게이츠] 지식활동보드를 통해 척척박사 컴퓨터를 구성하는 각 부분의 이름과 하는 일을 알아봅니다.','이달의 인물[컴퓨터 천재, 빌 게이츠] 동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (2,'JP030','C0015','P30','이달의 인물[노벨상에 담긴 약속, 노벨] 동화 전체 스토리를 파악하며 다이너마이트를 발명하고 전 세계의 평화와 행복을 위해 약속을 지킨 ‘노벨’을 만납니다. 동화 속 인물의 마음을 이해하고, 나의 감정을 표현해 보는 공감독서 시간을 갖습니다. ','이달의 인물[노벨상에 담긴 약속, 노벨] 즐겁게 불러보는 동요, 생각을 나누는 상상카드, 독서 왕을 뽑는 골든벨, 신나는 역할극 등 다양한 놀이를 통해 노벨과 친구가 됩니다.','이달의 인물[노벨상에 담긴 약속, 노벨] 지식활동보드를 통해 세계 평화를 위해 노력한 노벨평화상을 받은 인물에 대해 함께 알아봅니다.','이달의 인물[노벨상에 담긴 약속, 노벨] 동화 속 중심단어를 활용해 문장을 만든 후 차례대로 줄거리를 완성해 보는 한글 학습을 합니다.');

------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EGH001','C001','H01','<신나게 야호!>한자 이야기로 登, 心, 身을 배웁니다. 등산, 등교, 효심, 안심, 심신, 자신 등 단어와 교과서 속 활용문장을 익힙니다.','<달리기 연습>한자 이야기로 每 , 漢, 江을 배웁니다. 매일, 매년, 한자, 한문, 강산, 한강 등 단어와 교과서 속 활용문장을 익힙니다.','<하마 가족의 눈물>한자 이야기로 物, 園, 河을 배웁니다. 동물, 식물, 전원, 화원, 하마 ,하천 등 단어와 교과서 속 활용문장을 익힙니다.','<숲 속의 고물탑>한자 이야기로 古, 再, 用을 배웁니다. 고물, 고목, 재생, 재활, 활용, 용수등 단어와 교과서 속 활용문장을 익힙니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EGH002','C001','H02','<티격태격 그네 타기>한자 이야기로 共, 同, 使을 배웁니다. 공통,  공용, 공동, 동시, 사용, 천사 등 단어와 교과서 속 활용문장을 익힙니다. ','<효자가 사는 효자동>한자 이야기로 洞, 所, 聞을 배웁니다. 동구, 동장, 명소, 소중, 소문, 풍문 등 단어와 교과서 속 활용문장을 익힙니다. ','<불량식품 회의>한자 이야기로 不, 良, 品을 배웁니다. 불안, 부족, 양심, 불량, 식품, 명품 등 단어와 교과서 속 활용문장을 익힙니다. ','<노란색 노약자석>한자 이야기로 老, 弱, 者을 배웁니다. 노인, 노소, 노약, 약소, 기자, 학자 등 단어와 교과서 속 활용문장을 익힙니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EGH003','C001','H03','<알록달록 자연의 색깔>한자 이야기로 然, 綠, 色을 배웁니다. 자연, 천연, 녹색, 초록, 오색, 백색 등 단어와 교과서 속 활용문장을 익힙니다. ','<가을을 즐기는 추석>한자 이야기로 夕, 節, 族을 배웁니다. 추석, 칠석, 시절, 명절, 가족, 민족 등 단어와 교과서 속 활용문장을 익힙니다. ','<신나는 주말 보내기>한자 이야기로 週, 末, 場 을 배웁니다. 주일, 주간, 주말, 연말, 농장, 시장 등 단어와 교과서 속 활용문장을 익힙니다. ','<날아라 하늘 다람쥐>한자 이야기로 名, 現, 要을 배웁니다. 명언, 방언, 현장, 현금, 중요, 요지 등 단어와 교과서 속 활용문장을 익힙니다.   ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EGH004','C001','H04','<호추의 다짐>한자 이야기로 數, 計, 算을 배웁니다. 수학, 숫자, 시계, 합계, 계산, 산수 등 단어와 교과서 속 활용문장을 익힙니다. ','<가을은 독서의 계절>한자 이야기로 語, 讀, 書을 배웁니다. 국어, 언어, 독자, 다독, 독서, 양서 등 단어와 교과서 속 활용문장을 익힙니다.','<으쌰 으쌰! 체육대회>한자 이야기로 體, 育, 會을 배웁니다. 신체, 체중, 체육, 교육, 회장, 대회 등 단어와 교과서 속 활용문장을 익힙니다.','<나는 다정한 손녀>한자 이야기로 孫, 多, 情 을 배웁니다. 조손, 손자, 다소, 다독, 다정, 심정 등 단어와 교과서 속 활용문장을 익힙니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EGH005','C001','H05','<참 다행이야!>한자 이야기로 千, 萬, 幸을 배웁니다. 수천, 천금, 십만, 천만, 다행, 불행 등 단어와 교과서 속 활용문장을 익힙니다.','<도도리 작품 도난 사건>한자 이야기로 美, 術, 作을 배웁니다. 미남, 미녀, 미술, 화술, 작품, 작가 등 단어와 교과서 속 활용문장을 익힙니다.','<두더지 포포>한자 이야기로 說, 完, 成을 배웁니다. 설명, 소설, 완전, 완공, 완성, 성장 등 단어와 교과서 속 활용문장을 익힙니다.','<감기에 걸렸어요>한자 이야기로 感, 病, 院을 배웁니다. 감동, 감정, 병자, 문병, 병원, 학원 등 단어와 교과서 속 활용문장을 익힙니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EGH006','C001','H06','<두근두근 미래 사회>한자 이야기로 未, 來, 社을 배웁니다. 미안, 미완, 미래, 내일, 사회, 사장 등 단어와 교과서 속 활용문장을 익힙니다.','<한글을 만든 세종대왕>한자 이야기로 宗, 百, 姓을 배웁니다. 세종대왕, 종교, 백년, 구백, 백성, 성명 등 단어와 교과서 속 활용문장을 익힙니다.','<교가를 불러요>한자 이야기로 歌, 合, 唱을 배웁니다. 가수, 국가, 합력, 합동, 합창, 가창 등 단어와 교과서 속 활용문장을 익힙니다.','<꿈을 발표해요>한자 이야기로 今, 對, 答을 배웁니다. 고금, 금방, 대화, 대면, 정답, 대답 등 단어와 교과서 속 활용문장을 익힙니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EGH007','C001','H07','<으쌰! 학습지>한자 이야기로 習, 紙, 集을 배웁니다. 학습, 자습, 백지, 편지, 집합, 집중 등 단어와 교과서 속 활용문장을 익힙니다.','<알록달록 정원>한자 이야기로 里, 庭, 業을 배웁니다. 이장, 동리, 가정, 정원, 공업, 농업 등 단어와 교과서 속 활용문장을 익힙니다.','<어촌 체험학습>한자 이야기로 漁, 村 , 産을 배웁니다. 어부, 어업, 어촌, 농촌, 생산, 산모 등 단어와 교과서 속 활용문장을 익힙니다.','<발표는 자신감 있게!>한자 이야기로 信, 發, 表을 배웁니다. 자신감, 신용, 출발, 발견, 발표, 표현 등 단어와 교과서 속 활용문장을 익힙니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EGH008','C001','H08','<태양의 빛>한자 이야기로 太, 陽, 光을 배웁니다. 태고, 태반, 태양, 양지, 양지, 발광, 일광 등 단어와 교과서 속 활용문장을 익힙니다.','<아기 고래의 여행>한자 이야기로 球, 洋, 平을 배웁니다. 지구, 족구, 해양, 서양, 평지, 수평 등 단어와 교과서 속 활용문장을 익힙니다.','<우리 외삼촌 이야기>한자 이야기로 飮, 急, 苦을 배웁니다. 음식, 음수, 시급, 다급, 고생, 고심 등 단어와 교과서 속 활용문장을 익힙니다.','<병원에서는 조용히!>한자 이야기로 堂, 米, 問을 배웁니다. 식당, 서당, 백미, 미음, 문안, 문답 등 단어와 교과서 속 활용문장을 익힙니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EGH009','C001','H09','<신나는 놀이공원>한자 이야기로 公, 開, 放을 배웁니다. 공원, 공평, 공개, 개교, 개방, 방학 등 단어와 교과서 속 활용문장을 익힙니다.','<부산으로 가는 열차>한자 이야기로 列, 立, 席을 배웁니다. 열차, 일렬, 자립, 국립, 입석, 출석 등 단어와 교과서 속 활용문장을 익힙니다.','<한자시험>한자 이야기로 例, 題, 夫을 배웁니다. 예외, 예문, 화제, 문제, 공부, 농부 등 단어와 교과서 속 활용문장을 익힙니다.','<걱정되는 내 동생>한자 이야기로 雪, 主, 童을 배웁니다. 백설, 대설, 주인, 민주, 동화, 동심 등 단어와 교과서 속 활용문장을 익힙니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EGH010','C001','H10','<도로명 주소>한자 이야기로 番, 住, 路을 배웁니다. 번지, 매번, 주소, 주민, 도로, 통로 등 단어와 교과서 속 활용문장을 익힙니다.','<이 시대의 영웅>한자 이야기로 正, 直, 善을 배웁니다. 정답, 공정, 정직, 직후, 선량, 선심 등 단어와 교과서 속 활용문장을 익힙니다.','<가훈 발표>한자 이야기로 訓, 根, 本을 배웁니다. 가훈, 교훈, 초근, 모근, 근본, 본래 등 단어와 교과서 속 활용문장을 익힙니다.','<지우의 인사>한자 이야기로 事, 基, 禮을 배웁니다. 인사, 기사, 기본, 기지, 예절, 답례 등 단어와 교과서 속 활용문장을 익힙니다.');

INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EGL080','C001','L80','배정한자 64자. 어휘 130개로 기초 교과 어휘를 정리합니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EGL070','C001','L70','배정 한자 150자, 어휘 300개로 기본 교과 개념어를 정리합니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EGL060','C001','L60','배정한자 364자, 어휘 1200개로 일상생활에서 쓰는 기본적인 한자를 정리합니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EGL061','C001','L61','배정한자 200자, 어휘 600개로 일상생활에서 쓰는 기본적인 한자를 정리합니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EGL050','C001','L50','배정한자 600자 한자와 교과 개념어의 뜻을 정확히 이해하고 단어의 함축성과 상징적인 의미를 연습하기 시작합니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EGL051','C001','L51','배정한자 500자 한자와 개념어휘의 뜻을 정확히 이해하고 교과 내용을 쉽게 받아들이며 실생활에서 한자어를 활용할 수 있는 수업이 시작됩니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');

INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'ESH001','C002','H01','日, 月, 火, 水로 일출, 팔월, 화산, 수도 등 활용어휘를 익힙니다. 한자성어는 水魚之交를 배워요.','木, 金, 土, 口로 토양, 식목, 황금, 인구 등 활용어휘를 익힙니다. 한자성어는 十人十色을 배워요.','山, 川, 田, 力로 등산, 산천, 염전, 풍력 등 활용어휘를 익힙니다. 한자성어는 山川草木을 배워요.','大, 小, 靑, 白로 대문, 소아, 청색, 백마 등 활용어휘를 익힙니다. 한자성어는 身土不二를 배워요.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'ESH002','C002','H02','上, 下, 中, 人로 수상, 중간, 인형, 하차 등 활용어휘를 익힙니다. 한자성어는 一家花親을 배워요.','一, 二, 小, 年로 일등, 이층, 소녀, 내년 등 활용어휘를 익힙니다. 한자성어는 長幼有序를 배워요.','三, 四, 五, 六로 삼각형, 사계절, 오백원, 육대륙 등 활용어휘를 익힙니다. 한자성어는 一石二鳥를 배워요. ','七, 八, 九, 十로 북두칠성, 구구단, 팔월, 시월 등 활용어휘를 익힙니다. 한자성어는 同苦同樂을 배워요.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'ESH003','C002','H03','出, 入, 內, 外로 일출, 입구, 실내, 외출 등 활용어휘를 익힙니다. 한자성어는 三三五五를 배워요.','手, 足, 耳, 目로 박수, 수족, 이비인후과, 이목 등 활용어휘를 익힙니다. 한자성어는 九死一生을 배워요.','王, 子, 男, 女로 여왕, 남녀, 효자, 여자 등 활용어휘를 익힙니다. 한자성어는 春夏秋冬을 배워요.','父, 母, 兄, 弟로 부모, 사촌형, 모녀, 형제 등 활용어휘를 익힙니다. 한자성어는 美風良俗을 배워요.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'ESH004','C002','H04','東, 西, 南, 北로 동해, 서양인, 남극, 북극 등 활용어휘를 익힙니다. 한자성어는 正正堂堂을 배워요.','韓, 國, 民, 軍로 한복, 국민, 민속, 군인 등 활용어휘를 익힙니다. 한자성어는 東西古今을 배워요.','學, 校, 先, 生로 학생, 선생, 등교, 생일 등 활용어휘를 익힙니다. 한자성어는 家家戶戶를 배워요.','敎, 室, 門, 長로 교육, 거실, 창문, 선장 등 활용어휘를 익힙니다. 한자성어는 年中無休를 배워요.');

INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'ESL080','C002','L80','배정한자 64자. 어휘 130개로 기초 교과 어휘를 정리합니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'ESL070','C002','L70','배정 한자 150자, 어휘 300개로 기본 교과 개념어를 정리합니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'ESL060','C002','L60','배정한자 364자, 어휘 1200개로 일상생활에서 쓰는 기본적인 한자를 정리합니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'ESL061','C002','L61','배정한자 200자, 어휘 600개로 일상생활에서 쓰는 기본적인 한자를 정리합니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'ESL050','C002','L50','배정한자 600자 한자와 교과 개념어의 뜻을 정확히 이해하고 단어의 함축성과 상징적인 의미를 연습하기 시작합니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'ESL051','C002','L51','배정한자 500자 한자와 개념어휘의 뜻을 정확히 이해하고 교과 내용을 쉽게 받아들이며 실생활에서 한자어를 활용할 수 있는 수업이 시작됩니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');


INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EDH001','C003','H01','<돌돌이의 세계여행>한자 이야기로 界, 旅, 行 을 배웁니다. 세계, 외계인, 여중, 여로, 여행, 행동 등 단어와 교과서 속 활용문장을 익힙니다.','<저금하는 날>한자 이야기로 午, 銀, 貯 를 배웁니다. 오전, 오후, 은행, 은하, 저금, 저수 등 단어와 교과서 속 활용문장을 익힙니다. ','<금메달 리스트 우리 형!>한자 이야기로 新, 消, 息 을 배웁니다. 신문, 신년, 소화, 소식, 휴식, 자식 등 단어와 교과서 속 활용문장을 익힙니다. ','<일기 예보>한자 이야기로 溫, 衣. 服 을 배웁니다. 기온, 온실, 내의, 상의, 의복, 한복 등 단어와 교과서 속 활용문장을 익힙니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EDH002','C003','H02','<내 이름은 마틴 루서 킹>한자 이야기로 代, 由, 等 을 배웁니다. 현대, 대신, 자유, 사유, 동등, 평등 등 단어와 교과서 속 활용문장을 익힙니다. ','<주유소에 왔어요>한자 이야기로 注, 油, 洗 를 배웁니다. 주목, 주입, 주유, 석유, 세차, 세수 등 단어와 교과서 속 활용문장을 익힙니다. ','<우리는 친구>한자 이야기로 級, 分, 班 을 배웁니다. 학급, 등급, 기분, 분수, 분반, 반장 등 단어와 교과서 속 활용문장을 익힙니다. ','<토끼의 생일>한자 이야기로 音, 樂, 器 를 배웁니다. 발음, 음색, 음악, 고락, 악기, 변기 등 단어와 교과서 속 활용문장을 익힙니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EDH003','C003','H03','<아기 다람쥐 돌체>한자 이야기로 意, 見, 明 을 배웁니다. 동의, 주의, 의견, 견학, 분명, 발명 등 단어와 교과서 속 활용문장을 익힙니다. ','<말의 고저장단>한자 이야기로 高, 低, 短 을 배웁니다. 고공, 고급, 고저, 저하, 장단, 단문 등 단어와 교과서 속 활용문장을 익힙니다. ','<함께 편지를 써요>한자 이야기로 形, 式, 容 을 배웁니다. 형성, 지형, 형식, 방식, 미용, 내용 등 단어와 교과서 속 활용문장을 익힙니다. ','<입소문>한자 이야기로 映, 畵, 實 을 배웁니다. 방영, 상영, 화가, 영화, 실감, 실력 등 단어와 교과서 속 활용문장을 익힙니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EDH004','C003','H04','<운명의 한일전>한자 이야기로 半, 戰, 利 를 배웁니다. 전반, 후반, 휴전, 작전, 유리, 이용 등 단어와 교과서 속 활용문장을 익힙니다. ','<민석이의 일기>한자 이야기로 夜, 反, 省 을 배웁니다. 야간, 야광, 반대, 반감, 자성, 반성 등 단어와 교과서 속 활용문장을 익힙니다. ','<경수의 빛나는 순간>한자 이야기로 勝, 晝, 面을 배웁니다. 승리, 완승, 주야, 주간, 화면, 장면 등 단어와 교과서 속 활용문장을 익힙니다. ','<선분과 각도>한자 이야기로 線, 角, 度 를 배웁니다. 선분, 직선, 삼각, 직각, 온도, 각도 등 단어와 교과서 속 활용문장을 익힙니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EDH005','C003','H05','<태풍 부는 날>한자 이야기로 强, 窓,部 를 배웁니다. 강풍, 강약, 창문, 동창, 부분, 전부 등 단어와 교과서 속 활용문장을 익힙니다.','<과거와 현재> 한자 이야기로 過, 去, 在 를 배웁니다. 통과, 과식, 과거, 거래, 부재, 현재 등 단어와 교과서 속 활용문장을 익힙니다. ','<개구리 리티> 한자 이야기로 失, 敗, 功 을 배웁니다. 실례, 실수, 실패, 승패, 성공, 유공자 등 단어와 교과서 속 활용문장을 익힙니다. ','<혜민이네 과수원> 한자 이야기로 昨, 果, 樹 를 배웁니다. 작년, 작금, 과실, 성과, 과수, 수목 등 단어와 교과서 속 활용문장을 익힙니다. ');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EDH006','C003','H06','<특별활동>한자 이야기로 特 ,別, 各을 배웁니다. 특색, 특출, 특별, 별명, 각자, 각국 등 단어와 교과서 속 활용문장을 익힙니다.','<아프리카 초원에는>한자 이야기로 原, 種, 野을 배웁니다. 초원, 원유, 각종, 인종, 야생, 야외 등 단어와 교과서 속 활용문장을 익힙니다.','<아기 펭귄의 초대>한자 이야기로 辰, 招, 待을 배웁니다. 생신, 남진, 초래, 자초, 초대, 고대 등 단어와 교과서 속 활용문장을 익힙니다.','<비행기에서>한자 이야기로 親, 切, 案을 배웁니다. 부친, 친분, 친절, 절실, 안내, 답안 등 단어와 교과서 속 활용문장을 익힙니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EDH007','C003','H07','<용기 있는 시민들>한자 이야기로 勇, 申, 告을 배웁니다. 용기, 용자, 내신, 답신, 신고, 고발 등 단어와 교과서 속 활용문장을 익힙니다.','<신호등을 확인해요>한자 이야기로 號, 停, 止을 배웁니다. 신호, 번호, 정차, 정전, 정지, 중지 등 단어와 교과서 속 활용문장을 익힙니다.','<아기 다람쥐 미루>한자 이야기로 醫, 師, 藥을 배웁니다. 의원, 명의, 의사, 교사, 약사, 약초 등 단어와 교과서 속 활용문장을 익힙니다.','<천하제일 요리대회>한자 이야기로 第, 料, 理을 배웁니다. 제일, 제삼자, 음료, 요금, 요리, 도리 등 단어와 교과서 속 활용문장을 익힙니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EDH008','C003','H08','<통일의 꿈>한자 이야기로 和, 統, 遠을 배웁니다. 평화, 불화, 통일, 통합, 원대, 원양 등 단어와 교과서 속 활용문장을 익힙니다.','<이씨 아저씨>한자 이야기로 李, 氏, 近을 배웁니다. 이화, 이김, 이씨, 김씨, 친근, 원근 등 단어와 교과서 속 활용문장을 익힙니다.','<새해에는 운동해요>한자 이야기로 朴, 運, 始을 배웁니다. 박씨, 김박, 운동, 운행, 시작, 시조 등 단어와 교과서 속 활용문장을 익힙니다.','<도기와 카야>한자 이야기로 英, 才, 頭을 배웁니다. 영어, 영특, 영재, 천재, 두각, 선두 등 단어와 교과서 속 활용문장을 익힙니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EDH009','C003','H09','<도화지를 잊지마!>한자 이야기로 具, 店, 圖을 배웁니다. 문구, 가구, 서점, 점주, 도화, 지도 등 단어와 교과서 속 활용문장을 익힙니다.','<지킬 건 지켜요!>한자 이야기로 定, 速, 區을 배웁니다. 일정, 안정, 정속, 속도, 구간, 구분 등 단어와 교과서 속 활용문장을 익힙니다.','<미미의 다짐>한자 이야기로 終, 科, 宿을 배웁니다. 종일, 종업, 과학, 과목, 숙제, 숙소 등 단어와 교과서 속 활용문장을 익힙니다.','<가장 높은 태극기>한자 이야기로 極, 旗, 章을 배웁니다. 태극, 북극, 국기, 백기, 문장, 도장 등 단어와 교과서 속 활용문장을 익힙니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EDH010','C003','H10','<중국여행>한자 이야기로 首, 都, 京을 배웁니다. 수석, 수장, 수도, 도시, 상경, 북경 등 단어와 교과서 속 활용문장을 익힙니다.','<조선의 도읍, 한양>한자 이야기로 朝, 鮮, 邑을 배웁니다. 조석, 조식, 조선, 신선, 도읍, 읍민 등 단어와 교과서 속 활용문장을 익힙니다.','<하미 이야기>한자 이야기로 淸, 淨, 域을 배웁니다. 청명, 청풍, 청정, 정화, 해역, 지역 등 단어와 교과서 속 활용문장을 익힙니다.','<해리 공주의 사랑이야기>한자 이야기로 永, 久, 變을 배웁니다. 영원, 영생, 영구, 장구, 불변, 급변 등 단어와 교과서 속 활용문장을 익힙니다.');

INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EDL080','C003','L80','배정한자 64자. 어휘 130개로 기초 교과 어휘를 정리합니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EDL070','C003','L70','배정 한자 150자, 어휘 300개로 기본 교과 개념어를 정리합니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EDL060','C003','L60','배정한자 364자, 어휘 1200개로 일상생활에서 쓰는 기본적인 한자를 정리합니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EDL061','C003','L61','배정한자 200자, 어휘 600개로 일상생활에서 쓰는 기본적인 한자를 정리합니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EDL050','C003','L50','배정한자 600자 한자와 교과 개념어의 뜻을 정확히 이해하고 단어의 함축성과 상징적인 의미를 연습하기 시작합니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EDL051','C003','L51','배정한자 500자 한자와 개념어휘의 뜻을 정확히 이해하고 교과 내용을 쉽게 받아들이며 실생활에서 한자어를 활용할 수 있는 수업이 시작됩니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');

INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EPH001','C004','H01','自, 己, 時로 자전거, 자동, 자기, 이기심, 동시, 시계 등 활용어휘를 익힙니다. 한자성어는 竹馬故友를 배워요.','間, 食, 活로 중간, 간식, 음식, 식수, 활동, 활력 등 활용어휘를 익힙니다. 한자성어는 竹馬故友를 배워요.','花, 草, 植로 화초, 무궁화, 초가, 초록, 식물, 식목일 등 활용어휘를 익힙니다. 한자성어는 山明水淸을 배워요.','海, 石, 林로 해수욕장, 해외, 석공, 보석, 밀림, 산림 등 활용어휘를 익힙니다. 한자성어는 山明水淸을 배워요.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EPH002','C004','H02','家, 祖, 孝로 가족, 가구, 조부모, 조국, 효녀, 효도 등 활용어휘를 익힙니다. 한자성어는 父傳子傳을 배워요.','寸, 重, 記로 삼촌, 사촌, 소중, 체중, 일기, 기자 등 활용어휘를 익힙니다. 한자성어는 父傳子傳을 배워요.','方, 向, 左로 사방, 처방전, 방향, 향상, 좌회전, 좌측 등 활용어휘를 익힙니다. 한자성어는 相扶相助를 배워요. ','右, 前, 後로 우측, 우회전, 오전, 전진, 오후, 후반전 등 활용어휘를 익힙니다. 한자성어는 相扶相助를 배워요.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EPH003','C004','H03','牛, 羊, 馬로 우유, 한우, 산양, 양모, 마차, 승마 등 활용어휘를 익힙니다. 한자성어는 大器晩成을 배워요.','鳥, 犬, 魚로 백조, 조류, 애완견, 안내견, 어항, 대어 등 활용어휘를 익힙니다. 한자성어는 大器晩成을 배워요.','交, 通, 安로 교차로, 교환, 교통, 통로, 안녕, 편안 등 활용어휘를 익힙니다. 한자성어는 一絲不亂을 배워요.','全, 車, 道로 안전, 전신, 기차, 하차, 수도, 도로 등 활용어휘를 익힙니다. 한자성어는 一絲不亂을 배워요.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EPH004','C004','H04','春, 夏, 秋로 입춘, 춘추, 하계, 하복, 추석, 추수 등 활용어휘를 익힙니다. 한자성어는 溫故知新을 배워요.','冬, 風, 雨로 동지,동면, 풍차, 풍력, 우의, 우산, 등 활용어휘를 익힙니다. 한자성어는 溫故知新을 배워요.','文, 化, 有로 문화, 문구, 문화재, 화석, 유명, 소유 등 활용어휘를 익힙니다. 한자성어는 各人各色을 배워요.','名, 世, 字로 지명, 인명, 세계, 세종대왕, 문자, 숫자 등 활용어휘를 익힙니다. 한자성어는 各人各色을 배워요.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EPH005','C004','H05','天, 地, 空로 천지, 천사, 지구, 지도, 공군, 공중 등 활용어휘를 익힙니다. 한자성어는 多多益善을 배워요.','氣, 農, 市로 일기, 감기, 농부, 농장, 도시, 시장 등 활용어휘를 익힙니다. 한자성어는 多多益善을 배워요.','電, 話, 工로 가전, 충전, 전화, 동화, 공장, 목공 등 활용어휘를 익힙니다. 한자성어는 知行合一을 배워요.','動, 便, 休로 자동, 운동, 편리, 편지, 휴일, 휴식 등 활용어휘를 익힙니다.한자성어는 知行合一을 배워요. ');

INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EPL080','C004','L80','배정한자 64자. 어휘 130개로 기초 교과 어휘를 정리합니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');
