INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'EPL051','C004','L51','배정한자 500자 한자와 개념어휘의 뜻을 정확히 이해하고 교과 내용을 쉽게 받아들이며 실생활에서 한자어를 활용할 수 있는 수업이 시작됩니다.','어휘 활용을 통해 해당 급수 한자 읽기와 이하 급수 한자 쓰기를 정리합니다.','배정한자를 복습하고 문제집 풀이에 들어갑니다.','예상문제 풀이로 배운 내용을 확인합니다.');

INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'YH001','C006','H01','日(해일), 月(달월) 요일에 관계된 한자를 배우고 ‘노래하는 일주일’한자 노래도 불러봅니다. 또한 서로 떨어질 수 없는 친한 사이를 나타낸 ‘水魚之交(수어지교)’ 한자성어도 함께 익힙니다.','火(불화), 水(물수) 한자를 익히고 규칙적인 식생활 습관과 양치질을 잘하자는 내용인 ‘훈이의 일주일’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','木(나무목), 金(쇠금) 한자를 배우고 숨겨진 그림을 보며 떠올리는 놀이 컨텐츠를 통해 한자의 이미지를 그려봅니다. ','土(흙토), 口(입구) 한자를 배우고 한자카드 만들기와 한글 놀이터를 통해 한달간 배운 한자를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'YH002','C006','H02','山(메산), 川(내천) 자연에 관계된 한자를 배우고 ‘야호 야호’ 한자 노래를 함께 불러봅니다. 또한 산과 물과 나무와 풀, 자연을 의미하는 ‘山川草木(산천초목)’ 한자성어를 익힙니다.','田(밭전), 力(힘력) 한자를 배우고 자연과 가까이 지내며, 건강한 몸과 마음을 가꾸자는 내용인 ‘아빠처럼 되고 싶어요’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','大(큰대), 小(작을소) 한자를 배우고  숨겨진 그림을 보며 떠올리는 놀이 컨텐츠를 통해 한자의 이미지를 그려봅니다. ','靑(푸를청), 白(흰백) 한자를 배우고 한자카드 만들기와 한글 놀이터를 통해 한달간 배운 한자를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'YH003','C006','H03','上(위상), 下(아래하) 위치에 관계된 한자를 배우고 ‘어디 있을까’ 한자 노래를 함께 불러봅니다. 또한 가족이나 친척이 사이좋게 지냄을 나타낸 ‘一家和親(일가화친)’ 한자성어를 익힙니다. ','中(가운데중), 人(사람인) 한자를 배우고 아빠의 추억이 담긴 분식집에 함께 가는 내용인 ‘소망분식’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','一(한일), 二(두이) 한자를 익히고  숨겨진 그림을 보며 떠올리는 놀이 컨텐츠를 통해 한자의 이미지를 그려봅니다. ','少(적을소), 年(해년) 한자를 배우고 한자카드 만들기와 한글 놀이터를 통해 한달간 배운 한자를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'YH004','C006','H04','三(셋삼), 四(넷사) 숫자에 관계된 한자를 배우고 ‘숫자랑 한자랑’ 한자 노래를 함께 불러봅니다. 또한 한 가지 일로 두 가지의 이익을 얻는다는 ‘一石二鳥(일석이조)’ 한자성어를 익힙니다.  ','五(다섯오), 六(여섯륙) 한자를 배우고 친구들과 함께 숨바꼭질 하며 일어날 수 있는 이야기를 담은 ‘숨바꼭질’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','七(일곱칠), 八(여덟팔) 한자를 배우고  숨겨진 그림을 보며 떠올리는 놀이 컨텐츠를 통해 한자의 이미지를 그려봅니다. ','九(아홉구), 十(열십)한자를 배우고 한자카드 만들기와 한글 놀이터를 통해 한달간 배운 한자를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'YH005','C006','H05','出(날출), 入(들입) 한자를 배우고 ‘으쌰 으쌰 운동회’ 한자 노래를 함께 불러봅니다. 또한 삼사인이나 오륙인이 떼를 지은 모양을 뜻하는 ‘三三五五(삼삼오오)’ 한자성어를 익힙니다. ','內(안내), 外(바깥외) 한자를 배우고 몸이 불편한 장애인이 우리와 다르지 않다는 것을 담은 내용인 ‘나도 할 수 있어요’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','手(손수), 足(발족) 한자를 배우고  숨겨진 그림을 보며 떠올리는 놀이 컨텐츠를 통해 한자의 이미지를 그려봅니다. ','耳(귀이), 目(눈목) 한자를 배우고 한자카드 만들기와 한글 놀이터를 통해 한달간 배운 한자를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'YH006','C006','H06','王(임금왕), 子(아들자) 한자를 배우고 ‘우리가족’ 한자 노래를 함께 불러봅니다. 또한 봄/여름/가을/겨울의 네 계절을 나타내는 ‘春夏秋冬(춘하추동)’ 한자성어를 익힙니다.','男(사내남), 女(여자녀) 한자를 배우고 가족사진을 찍으며 가족의 소중함을 알아보는 내용인 ‘가족사진 찍는 날’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','父(아비부), 母(어미모) 한자를 배우고  숨겨진 그림을 보며 떠올리는 놀이 컨텐츠를 통해 한자의 이미지를 그려봅니다. ','兄(형형), 弟(아우제)한자를 배우고 한자카드 만들기와 한글 놀이터를 통해 한달간 배운 한자를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'YH007','C006','H07','東(동녘동), 西(서녘서) 방향에 관계된 한자를 배우고 ‘동서남북’ 한자 노래를 함께 불러봅니다. 또한 태도나 처지가 바르고 떳떳함을 나타내는 ‘正正堂堂(정정당당)’ 한자성어를 익힙니다.','南(남녘남), 北(북녘북) 한자를 배우고 세계 여러 나라의 특징을 알아보는 내용인 ‘세계지도’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','韓(나라한), 國(나라국) 한자를 배우고  숨겨진 그림을 보며 떠올리는 놀이 컨텐츠를 통해 한자의 이미지를 그려봅니다. ','民(백성민), 軍(군사군) 한자를 배우고 한자카드 만들기와 한글 놀이터를 통해 한달간 배운 한자를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'YH008','C006','H08','學(배울학), 校(학교교) 한자를 배우고 ‘안녕하세요 선생님’ 한자 노래를 함께 불러봅니다. 또한 집집마다라는 뜻을 가진 ‘家家戶戶(가가호호)’ 한자성어를 익힙니다','先(먼저선), 生(날생) 한자를 배우고 동물 친구들이 내가 만약 반장이 된다면 어떻게 할지 발표해보는 내용인 ‘반장선거’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','敎(가르칠교), 室(집실) 한자를 배우고  숨겨진 그림을 보며 떠올리는 놀이 컨텐츠를 통해 한자의 이미지를 그려봅니다. ','門(문문), 長(길장)한자를 배우고 한자카드 만들기와 한글 놀이터를 통해 한달간 배운 한자를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'YH009','C006','H09','<日月火水木金土口> ''요일''에 관계된 그림사전 속 사진들이 공통으로 의미하는 한자를 떠올리고 ‘노래하는 일주일’ 동요를 부르며 한자와 어울리는 그림을 붙여 퍼즐을 완성합니다.','<山川田力大小靑白>''자연''에 관계된 그림사전 속 사진들이 공통으로 의미하는 한자를 떠올리고 ‘야호야호’ 동요를 부르며 한자와 어울리는 그림을 붙여 퍼즐을 완성합니다.','<上下中人一二少年> ''위치''에 관계된 그림사전 속 사진들이 공통으로 의미하는 한자를 떠올리고 ‘어디 있을까’ 동요를 부르며 한자와 어울리는 그림을 붙여 퍼즐을 완성합니다.','<三四五六七八九十> ''숫자''에 관계된 그림사전 속 사진들이 공통으로 의미하는 한자를 떠올리고 ‘숫자랑 한자랑’ 동요를 부르며 한자와 어울리는 그림을 붙여 퍼즐을 완성합니다..');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'YH010','C006','H10','<出入內外手足耳目> ''신체''에 관계된 그림사전 속 사진들이 공통으로 의미하는 한자를 떠올리고 ‘으쌰으쌰 운동회’ 동요를 부르며 한자와 어울리는 그림을 붙여 퍼즐을 완성합니다.','<王子男女父母兄弟> ''가족''에 관계된 그림사전 속 사진들이 공통으로 의미하는 한자를 떠올리고 ‘우리가족’ 동요를 부르며 한자와 어울리는 그림을 붙여 퍼즐을 완성합니다.','<東西南北韓國民軍> ''방향''에 관계된 그림사전 속 사진들이 공통으로 의미하는 한자를 떠올리고 ‘동서남북’ 동요를 부르며 한자와 어울리는 그림을 붙여 퍼즐을 완성합니다.','<學校先生敎室門長> ''학교''에 관계된 그림사전 속 사진들이 공통으로 의미하는 한자를 떠올리고 ‘안녕하세요 선생님’ 동요를 부르며 한자와 어울리는 그림을 붙여 퍼즐을 완성합니다.');

INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'SH001','C007','H01','日, 月로 일출/생일/일월/삼월 등 활용어휘를 배우고 ‘요일송’ 한자노래도 불러봅니다. 또한 사람마다 성격과 좋아하는 것이 다르다는 뜻을 가진 ‘十人十色(십인십색)’ 한자성어도 함께 익힙니다.','火, 水로 소화기/화재/수도/음료수 등 활용어휘를 익히고 나와 다른 친구의 마음을 헤아리며 사이좋게 지내자는 내용을 담은 ‘장난꾸러기 데니’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','木, 金으로 목마/목수/황금/저금 등 활용어휘를 배우고 한자의 모양, 뜻, 소리를 맞추는 놀이 컨텐츠를 통해 한자의 정확한 뜻과 소리를 익힙니다. ','土, 口로 토목/농토/인구/입구 등 활용어휘를 익히고 한자어카드 만들기와 한글 놀이터를 통해 한달동안 배운 한자를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'SH002','C007','H02','山, 川으로 등산/빙산/산천/하천 등 활용어휘를 배우고 ‘자연송’ 한자노래도 불러봅니다. 또한 우리 땅에서 난 것이 우리 몸에 제일 잘 맞다는 뜻을 가진 ‘身土不二(신토불이)’ 한자성어도 함께 익힙니다.','田, 力으로 염전/전원/화력/역도 등 활용어휘를 익히고 자연을 소중히 여기며 환경보호를 실천하자는 주제를 담은 ‘북극곰은 어디로 가야 하나요’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','大, 小로 대문/확대/소아/소아과 등 활용어휘를 배우고 한자의 모양, 뜻, 소리를 맞추는 놀이 컨텐츠를 통해 한자의 정확한 뜻과 소리를 익힙니다. ','靑, 白으로 청백/청군/백인/백마 등 활용어휘를 익히고 한자어카드 만들기와 한글 놀이터를 통해 한달동안 배운 한자를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'SH003','C007','H03','上, 下로 수상/정상/하인/낙하산 등 활용어휘를 배우고 ‘위치송’ 한자노래도 불러봅니다. 또한 어른과 어린아이 사이에는 순서와 질서가 있다는 뜻을 가진 ‘長幼有序(장유유서)’ 한자성어도 함께 익힙니다.','中, 人으로 중앙/공중/인사/위인 등 활용어휘를 익히고 우리나라와 세계 여러 나라의 특징을 이해하는 ‘멀리 있지 않아요’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다. ','一, 二로 일등/일학년/이층/이인 등 활용어휘를 배우고 한자의 모양, 뜻, 소리를 맞추는 놀이 컨텐츠를 통해 한자의 정확한 뜻과 소리를 익힙니다. ','少, 年으로 소년/소녀/연중/매년 등 활용어휘를 익히고 한자어카드 만들기와 한글 놀이터를 통해 한달동안 배운 한자를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'SH004','C007','H04','三, 四로 삼일절/삼형제/사방/사계절 등 활용어휘를 배우고 ‘숫자송’ 한자노래도 불러봅니다. 또한 괴로움도 즐거움도 함께한다는 뜻을 가진 ‘同苦同樂(동고동락)’ 한자성어도 함께 익힙니다.','五, 六으로 오천원/오월오일/유월 육일/육대륙 등 활용어휘를 익히고 우리나라의 다양한 기념일과 명절을 소개하는 ‘달력을 넘기자’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다. ','七, 八으로 북두칠성/칠월 칠일/팔월 십오일/팔각형 등 활용어휘를 배우고 한자의 모양, 뜻, 소리를 맞추는 놀이 컨텐츠를 통해 한자의 정확한 뜻과 소리를 익힙니다. ','九, 十으로 구월/구미호/십삼/시월 등 활용어휘를 익히고 한자어카드 만들기와 한글 놀이터를 통해 한달동안 배운 한자를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'SH005','C007','H05','出, 入으로 출구/출발/입장/입수 등 활용어휘를 배우고 ‘신체송’ 한자노래도 불러봅니다. 또한 죽을 고비를 여러 차례 넘기고 겨우 살아난다는 뜻을 가진 ‘九死一生(구사일생)’ 한자성어도 함께 익힙니다.','內, 外로 내외/시내/외출/외국 등 활용어휘를 익히고 실내에서 지켜야 할 질서와 규칙을 알고 안전하게 생활하자는 주제를 담은 ‘안전 또 안전’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','手, 足으로 악수/박수/수족/족구 등 활용어휘를 배우고 한자의 모양, 뜻, 소리를 맞추는 놀이 컨텐츠를 통해 한자의 정확한 뜻과 소리를 익힙니다. ','耳, 目으로 이목구비/이비인후과/이목/주목 등 활용어휘를 익히고 한자어카드 만들기와 한글 놀이터를 통해 한달동안 배운 한자를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'SH006','C007','H06','王, 子로 왕관/대왕/부자/효자 등 활용어휘를 배우고 ‘가족송’ 한자노래도 불러봅니다. 또한 아름답고 좋은 풍속이라는 뜻을 가진 ‘美風良俗(미풍양속)’ 한자성어도 함께 익힙니다.','男, 女로 남자/남녀/부녀/여왕 등 활용어휘를 익히고 가족을 생각하며 사랑하는 마음을 표현하자는 내용을 담은 ‘첫만남’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','父, 母로 부모/조부/조모/모자 등 활용어휘를 배우고 한자의 모양, 뜻, 소리를 맞추는 놀이 컨텐츠를 통해 한자의 정확한 뜻과 소리를 익힙니다. ','兄, 弟로 형제/사촌형/제자/사제 등 활용어휘를 익히고 한자어카드 만들기와 한글 놀이터를 통해 한달동안 배운 한자를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'SH007','C007','H07','東, 西로 동해/동향/서양인/서향 등 활용어휘를 배우고 ‘나라송’ 한자노래도 불러봅니다. 또한 동양과 서양, 옛날과 지금이라는 뜻을 가진 ‘東西古今(동서고금)’ 한자성어도 함께 익힙니다.','南, 北으로 남극/남한/북극/북한 등 활용어휘를 익히고 우리 동네를 소개하는 ‘새별이의 편지’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','韓, 國으로 한옥/한복/출국/외국인 등 활용어휘를 배우고 한자의 모양, 뜻, 소리를 맞추는 놀이 컨텐츠를 통해 한자의 정확한 뜻과 소리를 익힙니다. ','民, 軍으로 국민/농민/군인/해군 등 활용어휘를 익히고 한자어카드 만들기와 한글 놀이터를 통해 한달동안 배운 한자를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'SH008','C007','H08','學, 校로 입학/학생/등교/교문 등 활용어휘를  배우고 ‘학교송’ 한자노래도 불러봅니다. 또한 한 해 동안 하루도 쉬는 날이 없다는 뜻을 가진 ‘年中無休(연중무휴)’ 한자성어도 함께 익힙니다.','先, 生으로 선생/선두/생일/생선 등 활용어휘를 익히고 환경의 소중함을 알고, 환경보호를 실천하자는 주제를 가진 ‘민우의 눈물’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','敎, 室로 교실/교구/거실/실내 등 활용어휘를 배우고 한자의 모양, 뜻, 소리를 맞추는 놀이 컨텐츠를 통해 한자의 정확한 뜻과 소리를 익힙니다. ','門, 長으로 교문/동문/교장/가장 등 활용어휘를 익히고 한자어카드 만들기와 한글 놀이터를 통해 한달동안 배운 한자를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'SH009','C007','H09','<日月火水木金土口>로 활용되는 단어의 뜻을 되새기고 지혜로운 사람이 되자는 교훈을 담은 ‘어린 사마광의 지혜’ 한자 이야기를 배웁니다.','<山川田力大小靑白>로 활용되는 단어의 뜻을 되새기고 부모님께 효도하자는 교훈을 담은 ‘효자 왕상’ 한자 이야기를 배웁니다.','<上中下人一二少年>로 활용되는 단어의 뜻을 되새기고 남의 장점과 단점을 말하지 말자는 교훈을 담은 ‘누런소와 검은 소’ 한자 이야기를 배웁니다.','<三四五六七八九十>로 활용되는 단어의 뜻을 되새기고 형제와 사이좋게 지내자는 교훈을 담은 ‘강에 던진 금덩어리’ 한자 이야기를 배웁니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'SH010','C007','H10','<出入內外手足耳目>로 활용되는 단어의 뜻을 되새기고 지혜로운 사람이 되자는 교훈을 담은 ‘어리석은 호랑이’ 한자 이야기를 배웁니다.','<王子男女父母兄弟>로 활용되는 단어의 뜻을 되새기고 끝까지 노력하면 꿈을 이룰 수 있다는 교훈을 담은 ‘산을 옮긴 우공’ 한자 이야기를 배웁니다.','<東西南北韓國民軍>로 활용되는 단어의 뜻을 되새기고 자기 자신을 사랑하자는 교훈을 담은 ‘두더지의 결혼’ 한자 이야기를 배웁니다.','<學校先生敎室門長>로 활용되는 단어의 뜻을 되새기고 열심히 노력하면 꿈을 이룰수 있다는 교훈을 담은 ‘반딧불이와 눈의 공적’ 한자 이야기를 배웁니다.');

INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'PH001','C008','H01','自, 己로 자전거/자동/이기적/자기 등 활용어휘를 익히고 ‘즐거운 유치원’ 한자노래를 불러봅니다. 또한 어릴 때 부터 같이 놀며 자란 친구라는 뜻을 가진 ‘竹馬故友(죽마고우)’ 한자성어도 배웁니다. ','時, 間으로 시간/조선시대/인간/중간 등 활용어휘를 익히고 단체생활을 할 땐 질서와 규칙을 지켜야 한다는 주제를 담은 ‘내 마음대로 할 거야’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','食, 活로 양식/음식/활기/활동 등 활용어휘를 익히고 같은 짝을 찾는 퍼즐놀이와 한자의 모양, 뜻, 소리를 맞추는 놀이 컨텐츠를 통해 한자의 정확한 뜻과 소리를 익힙니다. ','‘내 마음대로 할거야’ 한자동화 독서 골든벨과 한자어카드, 만들기를 하며 한 달 동안 배운 한자어를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'PH002','C008','H02','花, 草로 화단/무궁화/초록/초가 등 활용어휘를 익히고 ‘자연아 놀자’ 한자노래를 불러봅니다. 또한 산과 물이 맑고 깨끗하여 경치가 좋음을 나타내는 ‘山明水淸(산명수청)’ 한자성어도 배웁니다. ','植, 海으로 식목일/식물/해수욕장/해외 등 활용어휘를 익히고 자연이 오염되면 더 이상 볼 수 없는 이야기를 담은 ‘그리운 초록’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','石, 林으로 보석/자석/산림/밀림 등 활용어휘를 익히고 같은 짝을 찾는 퍼즐놀이와 한자의 모양 ,뜻, 소리를 맞추는 놀이 컨텐츠를 통해 한자의 정확한 뜻과 소리를 익힙니다. ','‘그리운 초록’ 한자동화 독서 골든벨과 한자어카드, 만들기를 하며 한 달 동안 배운 한자어를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'PH003','C008','H03','家, 祖로 초가/가족/조국/조부모 등 활용어휘를 익히고 ‘사랑하는 우리가족’ 한자노래를 불러봅니다. 또한 아들의 성격이나 생활 모습이 아버지와 같거나 비슷하다는 뜻을 가진 ‘父傳子傳(부전자전)’ 한자성어도 배웁니다. ','孝, 寸으로 효도/효녀/사촌/삼촌 등 활용어휘를 익히고 가족의 종류가 다양해도 모두 소중하다는 주제를 담은 ‘사랑의 가족’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','重, 記로 체중/소중/일기/기자 등 활용어휘를 익히고 같은 짝을 찾는 퍼즐놀이와 한자의 모양, 뜻, 소리를 맞추는 놀이 컨텐츠를 통해 한자의 정확한 뜻과 소리를 익힙니다. ','‘사랑의 가족’ 한자동화 독서 골든벨과 한자어카드, 만들기를 하며 한 달 동안 배운 한자어를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'PH004','C008','H04','方, 向으로 사방/처방전/향상/방향 등 활용어휘를 익히고 ‘동네한바퀴’ 한자노래도 불러봅니다. 또한 서로서로 돕는다는 뜻을 가진 ‘相扶相助(상부상조)’한자성어도 배웁니다.','左, 右로 좌회전/좌의정/우향/우측 등 활용어휘를 익히고 우리 동네의 모습과 방향에 대한 소개를 담은 ‘은이네집 가는길’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','前, 後로 오전/전진/오후/후반전 등 활용어휘를 익히고 같은 짝을 찾는 퍼즐놀이와 한자의 모양,뜻,소리를 맞추는 놀이 컨텐츠를 통해 한자의 정확한 뜻과 소리를 익힙니다. ','‘은이네집 가는길’ 한자동화 독서 골든벨과 한자어카드, 만들기를 하며 한 달 동안 배운 한자어를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'PH005','C008','H05','牛, 羊으로 한우/우유/산양/양모 등 활용어휘를 익히고 ‘동물 친구들’ 한자노래도 불러봅니다. 또한 여러 번 실패해도 굴하지 않고 꾸준히 노력한다는 뜻을 가진 ‘七顚八起(칠전팔기)’ 한자성어도 배웁니다','馬, 鳥로 마차/승마/백조/조류 등 활용어휘를 익히고 내가 키우고 싶은 동물에 이야기를 담은 ‘은지의 동물친구’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','犬, 魚로 안내견/애완견/어항/인어 등 활용어휘를 익히고 같은 짝을 찾는 퍼즐놀이와 한자의 모양, 뜻, 소리를 맞추는 놀이 컨텐츠를 통해 한자의 정확한 뜻과 소리를 익힙니다. ','‘은지의 동물친구’ 한자동화 독서 골든벨과 한자어카드, 만들기를 하며 한 달 동안 배운 한자어를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'PH006','C008','H06','交, 通으로 교차로/교환/교통/통로 등 활용어휘를 익히고 ‘뛰뛰빵빵 조심해요’ 한자노래도 불러봅니다. 또한 한 오라기의 실도 흐트러지지 않는다라는 뜻을 가진 ‘一絲不亂(일사불란)’ 한자성어도 배웁니다','安, 全으로 안녕/편안/안전/전신 등 활용어휘를 익히고 자동차의 특징과 교통안전의 중요성을 알아보는 ‘자동차 삼형제’ 동화를 통해 문장에서 한자의 쓰임을 배워봅니다.','車, 道로 하차/기차/도로/수도 등 활용어휘를 익히고 같은 짝을 찾는 퍼즐놀이와 한자의 모양, 뜻, 소리를 맞추는 놀이 컨텐츠를 통해 한자의 정확한 뜻과 소리를 익힙니다. ','‘자동차 삼형제’ 한자동화 독서 골든벨과 한자어카드, 만들기를 하며 한 달 동안 배운 한자어를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'PH007','C008','H07','春, 夏로 입춘/춘추/하복/하계 등 활용어휘를 익히고 ‘춘하추동 사계절’ 한자노래도 불러봅니다. 또한 옛것을 익히고 그것을 미루어 새것을 안다는 뜻을 가진 ‘溫故知新(온고지신)’ 한자성어도 배웁니다','秋, 冬으로 추석/추수/동지/동면 등 활용어휘를 익히고 우리나라의 가장 대표적인 24절기를 알아보는 ‘만복이의 춘하추동’ 동화를 통해 문장에서 한자의 쓰임을 배워봅니다.','風, 雨로 풍차/태풍/우산/우의 등 활용어휘를 익히고 같은 짝을 찾는 퍼즐놀이와 한자의 모양, 뜻, 소리를 맞추는 놀이 컨텐츠를 통해 한자의 정확한 뜻과 소리를 익힙니다. ','‘만복이의 춘하추동’ 한자동화 독서 골든벨과 한자어카드, 만들기를 하며 한 달 동안 배운 한자어를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'PH008','C008','H08','文, 化로 문자/문구/문화재/화장실 등 활용어휘를 익히고 ‘글자가 달라요’ 한자노래도 불러봅니다. 또한 사람마다 성격과 개성이 다르다는 뜻을 가진 ‘各人各色(각인각색)’ 한자성어도 배웁니다','有, 名으로 유명/소유/명소/명찰 등 활용어휘를 익히고 여러 나라의 국기에 담긴 의미를 알아보는 ‘펄럭펄럭 깃발 이야기’ 동화를 통해 문장에서 한자의 쓰임을 배워봅니다.','世, 字로 세종대왕/세계/한자/숫자 등 활용어휘를 익히고 같은 짝을 찾는 퍼즐놀이와 한자의 모양, 뜻, 소리를 맞추는 놀이 컨텐츠를 통해 한자의 정확한 뜻과 소리를 익힙니다. ','‘펄럭펄럭 국기 이야기’ 한자동화 독서 골든벨과 한자어카드, 만들기를 하며 한 달 동안 배운 한자어를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'PH009','C008','H09','天, 地로 천지/천사/지구/지도 등 활용어휘를 익히고 ‘지구가 아파요’ 한자노래도 불러봅니다. 또한 많으면 많을수록 좋다는 뜻을 가진  ‘多多益善(다다익선)’ 한자성어도 배웁니다','空, 氣로 공군/공기/감기/일기 등 활용어휘를 익히고 환경을 보호하기 위해 노력해야 한다는 주제를 담은 ‘지렁이와 노란꽃’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','農, 市로 농장/농부/도시/시장 등 활용어휘를 익히고 같은 짝을 찾는 퍼즐놀이와 한자의 모양, 뜻, 소리를 맞추는 놀이 컨텐츠를 통해 한자의 정확한 뜻과 소리를 익힙니다. ','‘지렁이와 노란꽃’ 한자동화독서 골든벨과 한자어카드, 만들기를 하며 한 달 동안 배운 한자어를 복습, 정리 합니다.');
INSERT INTO erp_before_class (class_type, before_class_key, class_key, unit_key, ju_1, ju_2, ju_3, ju_4) VALUES (1,'PH010','C008','H10','電, 話로 충전/가전제품/전화/동화 등 활용어휘를 익히고 ‘뚝딱뚝딱 만들어요’ 한자노래도 불러봅니다. 또한 지식과 행동이 서로 일치해야한다는 뜻을 가진 ‘知行合一(지행합일)’ 한자성어도 배웁니다.','工, 動으로 공장/목공/자동/운동 등 활용어휘를 익히고 여러 사람들이 함께 사용하는 곳에서 예절을 지켜야 된다는 주제를 담은 ‘엘리베이터야 미안해’ 동화를 통해 문장에서 한자의 쓰임을 알아봅니다.','便, 休로 편지/편리/휴일/휴식 등 활용어휘를 익히고 같은 짝을 찾는 퍼즐놀이와 한자의 모양, 뜻, 소리를 맞추는 놀이 컨텐츠를 통해 한자의 정확한 뜻과 소리를 익힙니다. ','‘엘리베이터야 미안해’ 한자동화 독서 골든벨과 한자어카드, 만들기를 하며 한 달 동안 배운 한자어를 복습, 정리 합니다.');